# NOTE: Respect Twitter's (X) Terms of Service and only download content you have rights to.
# This cell uses Twitter's internal web endpoints with your browser cookies (no official API).

# ===================== PASTE YOUR VALUES HERE =====================
USERNAME    = "PASTE_TWITTER_USERNAME_HERE"        # e.g., "jack" (without @)
AUTH_TOKEN  = "PASTE_YOUR_auth_token_COOKIE_HERE"  # from browser cookies for https://twitter.com
CT0         = "PASTE_YOUR_ct0_COOKIE_HERE"         # from browser cookies for https://twitter.com
WEB_BEARER  = "PASTE_CURRENT_WEB_BEARER_TOKEN_HERE"  # e.g., "AAAAAAAAA...." (Twitter web bearer)
OUTPUT_DIR  = "/content/twitter_media"             # folder to save images (auto-created if missing)

# Optional caps and pacing
MAX_PAGES        = 200     # safety cap on pagination pages
REQUEST_RETRIES  = 4       # how many times to retry timeline requests
DOWNLOAD_RETRIES = 3       # how many times to retry image downloads
SLEEP_MIN        = 0.8     # min seconds between timeline requests
SLEEP_MAX        = 1.8     # max seconds between timeline requests
# ================================================================

# Install deps (requests, tqdm typically preinstalled in Colab, but keep for completeness)
!pip -q install requests tqdm

import os
import time
import json
import random
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Set

import requests
from tqdm.auto import tqdm

# ---------- Helpers ----------
def ensure_values():
    missing = []
    if not USERNAME or USERNAME.strip().lower() in {"paste_twitter_username_here", "username"}:
        missing.append("USERNAME")
    if not AUTH_TOKEN or "PASTE_YOUR_auth_token" in AUTH_TOKEN:
        missing.append("AUTH_TOKEN")
    if not CT0 or "PASTE_YOUR_ct0" in CT0:
        missing.append("CT0")
    if not WEB_BEARER or "PASTE_CURRENT_WEB_BEARER_TOKEN_HERE" in WEB_BEARER:
        missing.append("WEB_BEARER")
    if missing:
        raise ValueError(f"Please paste valid values for: {', '.join(missing)}")

def build_session(auth_token: str, ct0: str, bearer: str) -> requests.Session:
    s = requests.Session()
    # Minimal, stable headers used by the web app
    s.headers.update({
        "Authorization": f"Bearer {bearer}",
        "x-csrf-token": ct0,
        "x-twitter-active-user": "yes",
        "x-twitter-client-language": "en",
        "accept": "*/*",
        "accept-language": "en-US,en;q=0.9",
        "referer": "https://twitter.com/",
        # A realistic desktop UA reduces the chance of anti-bot friction
        "user-agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36"
        ),
    })
    # Set cookies (domain .twitter.com so they apply to API subdomains)
    s.cookies.set("auth_token", auth_token, domain=".twitter.com")
    s.cookies.set("ct0", ct0, domain=".twitter.com")
    return s

def jitter_sleep(a: float, b: float):
    time.sleep(random.uniform(a, b))

def make_output_dir(base: str, username: str) -> str:
    out = os.path.join(base, username)
    Path(out).mkdir(parents=True, exist_ok=True)
    return out

def orig_image_url(url: str) -> str:
    # Ensure original size. pbs media often supports ?name=orig.
    if "?name=" in url:
        parts = url.split("?")
        qs = parts[1].split("&")
        qs = [kv for kv in qs if not kv.startswith("name=")]
        qs.append("name=orig")
        return parts[0] + "?" + "&".join(qs)
    elif "?" in url:
        return url + "&name=orig"
    else:
        return url + "?name=orig"

def parse_photo_urls_from_search_adaptive(resp: Dict) -> List[Tuple[str, str]]:
    """
    Extract (tweet_id, photo_url) from search/adaptive response.
    Only photo media (ignores videos/GIFs).
    """
    results = []
    tweets = resp.get("globalObjects", {}).get("tweets", {}) or {}
    for tid, tw in tweets.items():
        ext = tw.get("extended_entities", {}) or {}
        media_list = ext.get("media", []) or []
        for m in media_list:
            if m.get("type") == "photo":
                u = m.get("media_url_https") or m.get("media_url")
                if u:
                    results.append((tid, orig_image_url(u)))
    return results

def extract_next_cursor(resp: Dict) -> Optional[str]:
    """
    Extract the 'Bottom' cursor from search/adaptive timeline instructions.
    """
    timeline = resp.get("timeline", {}) or {}
    instructions = timeline.get("instructions", []) or []
    for instr in instructions:
        if "addEntries" in instr:
            entries = instr["addEntries"].get("entries", []) or []
            c = _find_bottom_cursor_in_entries(entries)
            if c:
                return c
        if "replaceEntry" in instr:
            entry = instr["replaceEntry"].get("entry", {}) or {}
            entries = [entry] if entry else []
            c = _find_bottom_cursor_in_entries(entries)
            if c:
                return c
    return None

def _find_bottom_cursor_in_entries(entries: List[Dict]) -> Optional[str]:
    for e in entries:
        content = e.get("content") or {}
        # Cursor can be nested as operation.content.cursorType/value
        if isinstance(content, dict):
            if content.get("entryType") == "TimelineTimelineItem":
                # not a cursor
                pass
            # Sometimes cursor entries use this structure
            if content.get("operation") and isinstance(content.get("operation"), dict):
                op = content["operation"]
                cursor = op.get("cursor") or {}
                if cursor.get("cursorType") == "Bottom":
                    val = cursor.get("value")
                    if val:
                        return val
            # Other times cursor is directly under content
            if content.get("cursorType") == "Bottom":
                val = content.get("value")
                if val:
                    return val
        # Some responses use entryId hints
        entry_id = e.get("entryId", "")
        if isinstance(entry_id, str) and "-cursor-bottom" in entry_id.lower():
            # Try common places for value
            for k in ("item", "content"):
                node = e.get(k) or {}
                if isinstance(node, dict):
                    val = node.get("value") or node.get("cursor", {}).get("value")
                    if val:
                        return val
    return None

def build_search_adaptive_params(username: str, cursor: Optional[str] = None) -> Dict[str, str]:
    # This mirrors the web client's search/adaptive requests for filter:images
    q = f"from:{username} filter:images"
    params = {
        "q": q,
        "tweet_mode": "extended",
        "count": "50",
        "query_source": "typed_query",
        "pc": "1",
        "spelling_corrections": "1",
        "ext": "mediaColor,altText,hasNftAvatar,voiceInfo,superFollowMetadata"
    }
    if cursor:
        params["cursor"] = cursor
    return params

def get_with_retries(session: requests.Session, url: str, params: Dict[str, str], retries: int = 3, sleep_min: float = 0.6, sleep_max: float = 1.2) -> requests.Response:
    last_err = None
    for attempt in range(1, retries + 1):
        try:
            r = session.get(url, params=params, timeout=30)
            if r.status_code == 200:
                return r
            # Handle transient 4xx/5xx with backoff
            last_err = RuntimeError(f"HTTP {r.status_code}: {r.text[:200]}")
        except requests.RequestException as e:
            last_err = e
        jitter_sleep(sleep_min, sleep_max)
    raise last_err if last_err else RuntimeError("Request failed without explicit error")

def download_with_retries(session: requests.Session, url: str, path: str, retries: int = 3) -> None:
    last_err = None
    for attempt in range(1, retries + 1):
        try:
            with session.get(url, stream=True, timeout=60) as r:
                if r.status_code != 200:
                    last_err = RuntimeError(f"Download HTTP {r.status_code} for {url}")
                else:
                    tmp_path = path + ".part"
                    with open(tmp_path, "wb") as f:
                        for chunk in r.iter_content(chunk_size=1024 * 128):
                            if chunk:
                                f.write(chunk)
                    os.replace(tmp_path, path)
                    return
        except requests.RequestException as e:
            last_err = e
        time.sleep(min(2 ** attempt, 8))
    raise last_err if last_err else RuntimeError(f"Failed to download {url}")

# ---------- Main ----------
try:
    ensure_values()
    session = build_session(AUTH_TOKEN, CT0, WEB_BEARER)

    out_dir = make_output_dir(OUTPUT_DIR, USERNAME)
    archive_file = os.path.join(out_dir, "downloaded_urls.txt")
    downloaded: Set[str] = set()
    if os.path.exists(archive_file):
        with open(archive_file, "r", encoding="utf-8") as f:
            for line in f:
                u = line.strip()
                if u:
                    downloaded.add(u)

    base_url = "https://api.twitter.com/2/search/adaptive.json"
    cursor = None
    page = 0
    total_new = 0

    while page < MAX_PAGES:
        page += 1
        params = build_search_adaptive_params(USERNAME, cursor)
        try:
            resp = get_with_retries(session, base_url, params, retries=REQUEST_RETRIES, sleep_min=SLEEP_MIN, sleep_max=SLEEP_MAX)
        except Exception as e:
            print(f"[Error] Timeline request failed on page {page}: {e}")
            break

        try:
            data = resp.json()
        except Exception as e:
            print(f"[Error] Failed to parse JSON on page {page}: {e}")
            break

        pairs = parse_photo_urls_from_search_adaptive(data)
        if not pairs and not extract_next_cursor(data):
            print("No more media or unable to find next cursor. Stopping.")
            break

        # Deduplicate per page
        new_urls = []
        for tid, url in pairs:
            if url not in downloaded:
                downloaded.add(url)
                new_urls.append((tid, url))

        if new_urls:
            for tid, url in tqdm(new_urls, desc=f"Page {page} downloads", leave=False):
                filename = f"{tid}_{os.path.basename(url.split('?')[0])}"
                dest = os.path.join(out_dir, filename)
                try:
                    download_with_retries(session, url, dest, retries=DOWNLOAD_RETRIES)
                except Exception as e:
                    print(f"[Warn] Failed to download {url}: {e}")
                else:
                    total_new += 1
        else:
            print(f"Page {page}: No new images found.")

        # Persist archive incrementally
        try:
            with open(archive_file, "w", encoding="utf-8") as f:
                for u in sorted(downloaded):
                    f.write(u + "\n")
        except Exception as e:
            print(f"[Warn] Failed to update archive file: {e}")

        next_cursor = extract_next_cursor(data)
        if not next_cursor:
            print("Reached end of timeline (no next cursor).")
            break
        cursor = next_cursor
        jitter_sleep(SLEEP_MIN, SLEEP_MAX)

    print(f"Done. Saved {total_new} new images to: {out_dir}")
    print(f"Archive file: {archive_file}")
except Exception as e:
    print(f"[Fatal] {e}")
    raise

Below is a short, step-by-step walkthrough, followed by a single-file Go program that compiles and runs end-to-end. It implements a GA for weight budgeting with min/max per-asset bounds and a sum-to-1 constraint.

Step-by-step GA overview and how constraints are enforced:
- Representation
  - Individual is a vector of weights (float64) that sum to 1 and respect per-asset bounds.
  - In code: type Individual and population pop in main.
- Fitness (objective)
  - Maximize expected return − lambda × variance, where variance is w^T Σ w.
  - In code: objective (uses dot and quadForm).
- Initialization
  - Start with random weight vectors and project them onto the bounded simplex (sum-to-1 and min/max).
  - In code: randomFeasibleWeights + projectToSimplexWithBounds.
- Selection
  - Tournament selection picks the best of k random individuals.
  - In code: tournamentSelect.
- Crossover
  - Uniform crossover chooses each gene from parent1 or parent2 with 50% probability.
  - In code: uniformCrossover.
- Mutation
  - Add Gaussian noise to genes with some probability, then repair via projection.
  - In code: mutate + projectToSimplexWithBounds in the main loop.
- Constraint handling (repair)
  - Project weights onto the bounded simplex using bisection on a Lagrange multiplier.
  - In code: projectToSimplexWithBounds.
- Main loop
  - Sort by fitness (sortByFitness), keep elites (copyIndividual), generate children (selection → crossover → mutation), repair (projection), re-evaluate (objective), and repeat for generations. Track bestIndividual.

Note: Save the code to main.go and run with: go run main.go.

```go
// main.go
package main

import (
	"fmt"
	"log"
	"math"
	"math/rand"
	"sort"
	"strings"
	"time"
)

type Individual struct {
	Weights []float64
	Fitness float64
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Example data: 5 assets (or budget categories)
	expectedReturns := []float64{0.12, 0.10, 0.07, 0.15, 0.09}
	cov := [][]float64{
		{0.10, 0.02, 0.04, 0.00, 0.01},
		{0.02, 0.08, 0.01, 0.03, 0.00},
		{0.04, 0.01, 0.12, 0.02, 0.02},
		{0.00, 0.03, 0.02, 0.15, 0.01},
		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)

	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%.6f, sum(max)=%.6f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma)
			mutate(&child2, mutationRate, mutationSigma)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop
		currentBest := bestIndividual(pop)

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

// Objective: maximize return - lambda * variance
func objective(w []float64, expected []float64, cov [][]float64, lambda float64) float64 {
	ret := dot(w, expected)
	variance := quadForm(w, cov)
	return ret - lambda*variance
}

// Create a random feasible weight vector summing to 1 within bounds.
func randomFeasibleWeights(n int, minW, maxW []float64) []float64 {
	w := make([]float64, n)
	sum := 0.0
	for i := 0; i < n; i++ {
		w[i] = rand.Float64() + 1e-12
		sum += w[i]
	}
	for i := 0; i < n; i++ {
		w[i] /= sum
	}
	projectToSimplexWithBounds(w, minW, maxW)
	return w
}

// Projects a vector w onto the simplex {y: sum y = 1, minW[i] <= y[i] <= maxW[i]}.
// Uses bisection on a Lagrange multiplier tau: y_i = clip(w_i - tau, minW[i], maxW[i]) such that sum_i y_i = 1.
func projectToSimplexWithBounds(w []float64, minW, maxW []float64) {
	n := len(w)

	// Feasibility check
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0 {
		copy(w, minW)
		return
	}
	if sumMax < 1.0 {
		copy(w, maxW)
		return
	}

	// Determine bounds for tau
	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i]  // if tau <= low => y_i = maxW[i]
		high := w[i] - minW[i] // if tau >= high => y_i = minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	// Bisection on tau
	for iter := 0; iter < 80; iter++ {
		tau := 0.5 * (tauLow + tauHigh)
		sum := 0.0
		for i := 0; i < n; i++ {
			v := w[i] - tau
			if v < minW[i] {
				v = minW[i]
			}
			if v > maxW[i] {
				v = maxW[i]
			}
			sum += v
		}
		if sum > 1.0 {
			// Need to reduce sum -> increase tau
			tauLow = tau
		} else {
			// Need to increase sum -> decrease tau
			tauHigh = tau
		}
	}

	tau := 0.5 * (tauLow + tauHigh)
	for i := 0; i < n; i++ {
		v := w[i] - tau
		if v < minW[i] {
			v = minW[i]
		}
		if v > maxW[i] {
			v = maxW[i]
		}
		w[i] = v
	}

	// Optional tiny correction for numerical drift
	sum := 0.0
	freeIdx := make([]int, 0, n)
	for i := 0; i < n; i++ {
		sum += w[i]
		if w[i] > minW[i]+1e-12 && w[i] < maxW[i]-1e-12 {
			freeIdx = append(freeIdx, i)
		}
	}
	diff := 1.0 - sum
	if math.Abs(diff) > 1e-10 && len(freeIdx) > 0 {
		step := diff / float64(len(freeIdx))
		for _, i := range freeIdx {
			w[i] += step
			if w[i] < minW[i] {
				w[i] = minW[i]
			}
			if w[i] > maxW[i] {
				w[i] = maxW[i]
			}
		}
	}
}

// Tournament selection (maximization): pick 'k' random individuals, return the best
func tournamentSelect(pop []Individual, k int) Individual {
	best := pop[rand.Intn(len(pop))]
	for i := 1; i < k; i++ {
		cand := pop[rand.Intn(len(pop))]
		if cand.Fitness > best.Fitness {
			best = cand
		}
	}
	return best
}

// Uniform crossover: for each gene, pick from parent1 or parent2 with p=0.5
func uniformCrossover(p1, p2 Individual) (Individual, Individual) {
	n := len(p1.Weights)
	child1 := Individual{Weights: make([]float64, n)}
	child2 := Individual{Weights: make([]float64, n)}
	for i := 0; i < n; i++ {
		if rand.Float64() < 0.5 {
			child1.Weights[i] = p1.Weights[i]
			child2.Weights[i] = p2.Weights[i]
		} else {
			child1.Weights[i] = p2.Weights[i]
			child2.Weights[i] = p1.Weights[i]
		}
	}
	// Fitness will be recomputed after repair
	child1.Fitness = 0.0
	child2.Fitness = 0.0
	return child1, child2
}

// mutate adds Gaussian noise to each gene with probability mutationRate
func mutate(ind *Individual, mutationRate, mutationSigma float64) {
	for i := range ind.Weights {
		if rand.Float64() < mutationRate {
			ind.Weights[i] += mutationSigma * rand.NormFloat64()
		}
	}
	// Note: projection + fitness recalculation happens in the main loop.
}

// copyIndividual creates a deep copy of an individual
func copyIndividual(ind Individual) Individual {
	w := make([]float64, len(ind.Weights))
	copy(w, ind.Weights)
	return Individual{Weights: w, Fitness: ind.Fitness}
}

// sortByFitness sorts a population by fitness in descending order and returns it
func sortByFitness(pop []Individual) []Individual {
	sort.Slice(pop, func(i, j int) bool {
		return pop[i].Fitness > pop[j].Fitness
	})
	return pop
}

// bestIndividual returns the individual with the highest fitness
func bestIndividual(pop []Individual) Individual {
	best := pop[0]
	for i := 1; i < len(pop); i++ {
		if pop[i].Fitness > best.Fitness {
			best = pop[i]
		}
	}
	return best
}

// dot computes the dot product of two vectors
func dot(a, b []float64) float64 {
	if len(a) != len(b) {
		panic("dot: length mismatch")
	}
	sum := 0.0
	for i := 0; i < len(a); i++ {
		sum += a[i] * b[i]
	}
	return sum
}

// quadForm computes w^T * cov * w
func quadForm(w []float64, cov [][]float64) float64 {
	n := len(w)
	sum := 0.0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			sum += w[i] * cov[i][j] * w[j]
		}
	}
	return sum
}

// pretty formats a slice of float64 nicely
func pretty(w []float64) string {
	var b strings.Builder
	b.WriteString("[")
	for i, v := range w {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(fmt.Sprintf("%.4f", v))
	}
	b.WriteString("]")
	return b.String()
}
```

Genetic algorithms (GAs) are evolutionary search heuristics that optimize problems by iteratively evolving a population of candidate solutions. They apply selection (favoring fitter solutions), crossover (recombining parents), and mutation (introducing diversity) to explore complex search spaces. In finance/budgeting, GAs can handle non-linear objectives, discrete constraints, and hard bounds without requiring gradients. Benefits include flexibility and robustness to complex constraints; limitations include potentially slower convergence than convex solvers and the need for hyperparameter tuning with no guarantee of global optimality.

Brief walkthrough of the GA and constraints in the code:
- Representation: Individual holds a slice of weights and a fitness score.
- Fitness: objective = expected return minus lambda times variance, using dot and quadForm.
- Initialization: randomFeasibleWeights creates random weights, then projectToSimplexWithBounds enforces per-asset bounds and the sum-to-1 constraint.
- Selection: tournamentSelect picks the best among k random candidates.
- Crossover: uniformCrossover recombines parent genes with 50% probability per gene.
- Mutation: mutate adds Gaussian noise to weights; repaired afterwards via projection.
- Constraint handling: projectToSimplexWithBounds uses bisection on a Lagrange multiplier to project onto the bounded simplex (min/max per asset, sum equals 1).
- Main loop: sortByFitness for elitism, then selection → crossover → mutation → repair → reevaluate, track bestIndividual, repeat for generations.

