static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int len = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0);
    std::wstring out(len, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), (int)s.size(), out.data(), len);
    return out;
}

static std::string WideToUtf8(const std::wstring& s) {
    if (s.empty()) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0, nullptr, nullptr);
    std::string out(len, '\0');
    WideCharToMultiByte(CP_UTF8, 0, s.c_str(), (int)s.size(), out.data(), len, nullptr, nullptr);
    return out;
}

static std::wstring FormatWinHttpError(DWORD err) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(
        FORMAT_MESSAGE_FROM_HMODULE | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
        GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown WinHTTP error)";
    if (buf) LocalFree(buf);
    return s;
}

static std::wstring FormatLastError() {
    DWORD err = GetLastError();
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(
        FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_IGNORE_INSERTS,
        nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring s = (len && buf) ? std::wstring(buf, len) : L"(unknown error)";
    if (buf) LocalFree(buf);
    return s;
}

struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET x) : h(x) {}
    ~WinHttpHandle() { if (h) WinHttpCloseHandle(h); }
    operator HINTERNET() const { return h; }
};

static bool HttpRequest(const std::wstring& method,
                        const std::wstring& url,
                        const std::string& body,
                        std::map<std::wstring, std::wstring> extra_headers,
                        std::string& out_body,
                        DWORD timeout_ms = 15000) {
    out_body.clear();

    URL_COMPONENTS uc{0};
    uc.dwStructSize = sizeof(uc);
    std::wstring host, path;
    wchar_t host_buf[512] = {0};
    wchar_t path_buf[2048] = {0};
    uc.lpszHostName = host_buf; uc.dwHostNameLength = _countof(host_buf);
    uc.lpszUrlPath = path_buf; uc.dwUrlPathLength = _countof(path_buf);

    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n";
        return false;
    }

    bool https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    INTERNET_PORT port = uc.nPort ? uc.nPort : (https ? 443 : 80);
    host.assign(uc.lpszHostName, uc.dwHostNameLength);
    path.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (path.empty()) path = L"/";

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    WinHttpSetTimeouts(hSession, timeout_ms, timeout_ms, timeout_ms, timeout_ms);

    WinHttpHandle hConnect(WinHttpConnect(hSession, host.c_str(), port, 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(),
                                              nullptr, WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    std::wstringstream hdrs;
    hdrs << L"Accept: */*\r\n" << L"User-Agent: WinHTTP-Sample/1.0\r\n";
    for (auto& kv : extra_headers) {
        hdrs << kv.first << L": " << kv.second << L"\r\n";
    }
    std::wstring hdrs_str = hdrs.str();

    DWORD total_len = body.empty() ? 0 : (DWORD)body.size();
    if (!WinHttpSendRequest(hRequest, hdrs_str.c_str(), (DWORD)-1L,
                            body.empty() ? WINHTTP_NO_REQUEST_DATA : (LPVOID)body.data(),
                            total_len, total_len, 0)) {
        std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n";
        return false;
    }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n";
        return false;
    }

    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n";
            return false;
        }
        if (avail == 0) break;
        std::vector<char> chunk(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, chunk.data(), avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n";
            return false;
        }
        out_body.append(chunk.data(), chunk.data() + read);
    }

    DWORD status = 0; DWORD len = sizeof(status);
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, nullptr, &status, &len, nullptr);
    if (status >= 400) {
        std::wcerr << L"HTTP error status: " << status << L"\n";
        return false;
    }
    return true;
}

struct RelayInfo { std::string nickname; std::string identity; std::string address; int or_port = 0; };

static std::vector<RelayInfo> ParseConsensus(const std::string& text) {
    std::vector<RelayInfo> relays;
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            std::istringstream ls(line);
            std::string tag; ls >> tag; // r
            RelayInfo cur; std::string published1, published2;
            ls >> cur.nickname >> cur.identity >> cur.address >> cur.or_port >> published1 >> published2;
            if (!cur.nickname.empty() && !cur.address.empty()) relays.push_back(cur);
        }
    }
    return relays;
}

struct HSDescriptor {
    std::string onion_address_b32;
    std::vector<std::string> intro_points;
};

static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor d;
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("onion-address ", 0) == 0) {
            d.onion_address_b32 = line.substr(std::string("onion-address ").size());
        } else if (line.rfind("introduction-point ", 0) == 0) {
            d.intro_points.push_back(line.substr(std::string("introduction-point ").size()));
        }
    }
    return d;
}

static void OpenSSLInit() {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();
    OpenSSL_add_all_algorithms();
}

static void OpenSSLCleanup() {
    EVP_cleanup();
    ERR_free_strings();
}

static void PrintUsage() {
    std::wcout << L"Usage:\n"
               << L"  --consensus-url <https_url>     Download and parse Tor consensus (plaintext parsing).\n"
               << L"  --descriptor-url <https_url>    Download and parse HS v3 descriptor (plaintext parsing).\n"
               << L"  --get <https_url>               Perform HTTPS GET using WinHTTP.\n"
               << L"  --post <https_url> <data>       Perform HTTPS POST using WinHTTP.\n";
}

int wmain(int argc, wchar_t* argv[]) {
    OpenSSLInit();
    int ret = 0;

    auto do_get = [&](const std::wstring& url){
        std::string body;
        if (!HttpRequest(L"GET", url, "", {}, body)) return false;
        std::wcout << L"GET ok, bytes: " << body.size() << L"\n";
        return true;
    };
    auto do_post = [&](const std::wstring& url, const std::string& data){
        std::map<std::wstring, std::wstring> h{{L"Content-Type", L"application/x-www-form-urlencoded"}};
        std::string body;
        if (!HttpRequest(L"POST", url, data, h, body)) return false;
        std::wcout << L"POST ok, bytes: " << body.size() << L"\n";
        return true;
    };

    if (argc < 3) { PrintUsage(); OpenSSLCleanup(); return 0; }

    for (int i = 1; i < argc; ++i) {
        std::wstring arg = argv[i];
        if (arg == L"--get" && i + 1 < argc) {
            if (!do_get(argv[++i])) ret = 1;
        } else if (arg == L"--post" && i + 2 < argc) {
            std::wstring urlw = argv[++i];
            std::string data = WideToUtf8(argv[++i]);
            if (!do_post(urlw, data)) ret = 1;
        } else if (arg == L"--consensus-url" && i + 1 < argc) {
            std::wstring urlw = argv[++i];
            std::string text;
            if (!HttpRequest(L"GET", urlw, "", {}, text)) { ret = 1; continue; }
            auto relays = ParseConsensus(text);
            std::wcout << L"Parsed relays: " << relays.size() << L"\n";
            size_t shown = 0;
            for (const auto& r : relays) {
                if (shown++ >= 10) break;
                std::wcout << L"  " << Utf8ToWide(r.nickname) << L" " << Utf8ToWide(r.address)
                           << L":" << r.or_port << L"\n";
            }
        } else if (arg == L"--descriptor-url" && i + 1 < argc) {
            std::wstring urlw = argv[++i];
            std::string text;
            if (!HttpRequest(L"GET", urlw, "", {}, text)) { ret = 1; continue; }
            auto desc = ParseHSDescriptor(text);
            std::wcout << L"Descriptor onion-address: " << Utf8ToWide(desc.onion_address_b32) << L"\n";
            std::wcout << L"Intro points: " << desc.intro_points.size() << L"\n";
        } else {
            std::wcout << L"Unknown or malformed arguments.\n";
            PrintUsage();
            break;
        }
    }

    OpenSSLCleanup();
    return ret;
}

