static std::wstring FormatWinHttpError(DWORD err){ LPWSTR buf=nullptr; DWORD len=FormatMessageW(FORMAT_MESSAGE_FROM_HMODULE|FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_IGNORE_INSERTS, GetModuleHandleW(L"winhttp.dll"), err, 0, (LPWSTR)&buf, 0, nullptr); std::wstring s=(len&&buf)?std::wstring(buf,len):L"(unknown WinHTTP error)"; if(buf) LocalFree(buf); return s; }
static std::wstring FormatLastError(){ DWORD err=GetLastError(); LPWSTR buf=nullptr; DWORD len=FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_IGNORE_INSERTS,nullptr,err,0,(LPWSTR)&buf,0,nullptr); std::wstring s=(len&&buf)?std::wstring(buf,len):L"(unknown error)"; if(buf) LocalFree(buf); return s; }

// RAII WinHTTP
struct WinHttpHandle{ HINTERNET h{nullptr}; WinHttpHandle()=default; explicit WinHttpHandle(HINTERNET x):h(x){} ~WinHttpHandle(){ if(h) WinHttpCloseHandle(h);} WinHttpHandle(const WinHttpHandle&)=delete; WinHttpHandle& operator=(const WinHttpHandle&)=delete; WinHttpHandle(WinHttpHandle&& o) noexcept: h(o.h){ o.h=nullptr;} WinHttpHandle& operator=(WinHttpHandle&& o) noexcept{ if(this!=&o){ if(h) WinHttpCloseHandle(h); h=o.h; o.h=nullptr;} return *this;} operator HINTERNET() const { return h; } };

struct ParsedUrl{ std::wstring host; std::wstring path; INTERNET_PORT port{0}; bool https{false}; };

static bool CrackUrl(const std::wstring& url, ParsedUrl& out){ URL_COMPONENTS uc{}; wchar_t host[512]{}; wchar_t path[4096]{}; uc.dwStructSize=sizeof(uc); uc.lpszHostName=host; uc.dwHostNameLength=ARRSIZE(host); uc.lpszUrlPath=path; uc.dwUrlPathLength=ARRSIZE(path); uc.dwSchemeLength=(DWORD)-1; if(!WinHttpCrackUrl(url.c_str(),0,0,&uc)){ std::wcerr<<L"WinHttpCrackUrl failed: "<<FormatLastError()<<L"\n"; return false;} out.host.assign(uc.lpszHostName, uc.dwHostNameLength); out.path.clear(); if(uc.lpszUrlPath && uc.dwUrlPathLength) out.path.append(uc.lpszUrlPath, uc.dwUrlPathLength); if(uc.lpszExtraInfo && uc.dwExtraInfoLength) out.path.append(uc.lpszExtraInfo, uc.dwExtraInfoLength); if(out.path.empty()) out.path=L"/"; out.port=uc.nPort; out.https=(uc.nScheme==INTERNET_SCHEME_HTTPS); return true; }

// HTTPS GET/POST
static bool HttpRequest(const std::wstring& url, const std::wstring& method, const std::string* body, std::string& out){ out.clear(); ParsedUrl pu; if(!CrackUrl(url, pu)) return false; WinHttpHandle sess(WinHttpOpen(L"WinHTTP Client/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0)); if(!sess){ std::wcerr<<L"WinHttpOpen failed: "<<FormatLastError()<<L"\n"; return false;} WinHttpHandle conn(WinHttpConnect(sess, pu.host.c_str(), pu.port?pu.port:(pu.https?443:80), 0)); if(!conn){ std::wcerr<<L"WinHttpConnect failed: "<<FormatLastError()<<L"\n"; return false;} DWORD flags = pu.https ? WINHTTP_FLAG_SECURE : 0; WinHttpHandle req(WinHttpOpenRequest(conn, method.c_str(), pu.path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags)); if(!req){ std::wcerr<<L"WinHttpOpenRequest failed: "<<FormatLastError()<<L"\n"; return false; }
    BOOL bres=TRUE; if(body){ std::wstring headers=L"Content-Type: application/x-www-form-urlencoded\r\n"; bres=WinHttpSendRequest(req, headers.c_str(), (DWORD)headers.size(), (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0); } else { bres=WinHttpSendRequest(req, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);} if(!bres){ std::wcerr<<L"WinHttpSendRequest failed: "<<FormatLastError()<<L"\n"; return false; }
    if(!WinHttpReceiveResponse(req,nullptr)){ std::wcerr<<L"WinHttpReceiveResponse failed: "<<FormatLastError()<<L"\n"; return false; }
    DWORD status=0, len=sizeof(status); if(WinHttpQueryHeaders(req, WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &len, WINHTTP_NO_HEADER_INDEX)){ if(status<200 || status>=300){ std::wcerr<<L"HTTP status: "<<status<<L"\n"; }}
    for(;;){ DWORD avail=0; if(!WinHttpQueryDataAvailable(req,&avail)){ std::wcerr<<L"WinHttpQueryDataAvailable failed: "<<FormatLastError()<<L"\n"; return false;} if(!avail) break; std::string buf; buf.resize(avail); DWORD read=0; if(!WinHttpReadData(req, buf.data(), avail, &read)){ std::wcerr<<L"WinHttpReadData failed: "<<FormatLastError()<<L"\n"; return false;} buf.resize(read); out.append(buf); }
    return true; }

static bool HttpGet(const std::wstring& url, std::string& out){ return HttpRequest(url, L"GET", nullptr, out); }
static bool HttpPost(const std::wstring& url, const std::string& data, std::string& out){ return HttpRequest(url, L"POST", &data, out); }

// OpenSSL init
struct OpenSSLGlobal{ OpenSSLGlobal(){ OPENSSL_init_ssl(0,nullptr); OPENSSL_init_crypto(0,nullptr);} ~OpenSSLGlobal(){} } g_openssl;

// Simple line splitter
static std::vector<std::string> SplitLines(const std::string& s){ std::vector<std::string> lines; std::string cur; for(char c: s){ if(c=='\n'){ if(!cur.empty() && cur.back()=='\r') cur.pop_back(); lines.push_back(cur); cur.clear(); } else { cur.push_back(c);} } if(!cur.empty()) lines.push_back(cur); return lines; }

// Minimal Tor consensus parser
struct Relay{ std::string nickname; std::string identity; std::string ip; uint16_t orport{0}; std::vector<std::string> flags; };
static std::vector<Relay> ParseConsensus(const std::string& txt){ std::vector<Relay> relays; Relay cur; bool inRouter=false; auto emit=[&](){ if(!cur.nickname.empty()) relays.push_back(cur); cur=Relay{}; inRouter=false; }; for(const auto& line: SplitLines(txt)){ if(line.size()>2 && line[0]=='r' && line[1]==' '){ if(inRouter) emit(); inRouter=true; std::istringstream is(line); char r; is>>r; is>>cur.nickname; std::string ident_b64; std::string digest_b64; is>>ident_b64>>digest_b64>>cur.ip; uint16_t orport=0, dirport=0; is>>orport>>dirport; cur.orport=orport; cur.identity=ident_b64; } else if(inRouter && line.size()>2 && line[0]=='s' && line[1]==' '){ cur.flags.clear(); std::istringstream is(line.substr(2)); std::string flag; while(is>>flag) cur.flags.push_back(flag); } }
 if(inRouter) emit(); return relays; }

// Minimal HS v3 descriptor parser
struct HSDescriptor{ std::map<std::string,std::string> fields; std::vector<std::string> intro_points; };
static HSDescriptor ParseHSDescriptor(const std::string& txt){ HSDescriptor d; for(const auto& line: SplitLines(txt)){ if(line.rfind("introduction-point ",0)==0){ d.intro_points.push_back(line.substr(strlen("introduction-point "))); } else { auto p=line.find(' '); if(p!=std::string::npos){ d.fields[line.substr(0,p)]=line.substr(p+1); } } } return d; }

// CLI
static void PrintUsage(){ std::cout<<
"Usage:\n"
"  --consensus-url <https://...>      Download and parse Tor consensus\n"
"  --descriptor-url <https://...>     Download and parse HS v3 descriptor (plaintext)\n"
"  --get <https://...>                HTTPS GET to a regular URL\n"
"  --post <https://...> <data>        HTTPS POST to a regular URL\n"; }

int wmain(int argc, wchar_t** argv){ if(argc<3){ PrintUsage(); return 1; }
    std::vector<std::wstring> args(argv+1, argv+argc);
    for(size_t i=0;i<args.size();){ if(args[i]==L"--consensus-url" && i+1<args.size()){ std::wstring url=args[i+1]; i+=2; std::string body; if(!HttpGet(url, body)){ std::wcerr<<L"Failed to download consensus\n"; return 2; } auto relays=ParseConsensus(body); std::cout<<"Consensus relays parsed: "<<relays.size()<<"\n"; size_t show=std::min<size_t>(relays.size(),5); for(size_t k=0;k<show;++k){ const auto& r=relays[k]; std::cout<<"- "<<r.nickname<<" "<<r.ip<<":"<<r.orport<<" flags="; for(size_t j=0;j<r.flags.size();++j){ if(j) std::cout<<","; std::cout<<r.flags[j]; } std::cout<<"\n"; }
    } else if(args[i]==L"--descriptor-url" && i+1<args.size()){ std::wstring url=args[i+1]; i+=2; std::string body; if(!HttpGet(url, body)){ std::wcerr<<L"Failed to download descriptor\n"; return 3; } auto d=ParseHSDescriptor(body); std::cout<<"Descriptor fields: "<<d.fields.size()<<" intro_points: "<<d.intro_points.size()<<"\n"; size_t shown=0; for(const auto& kv: d.fields){ if(shown++>=8) break; std::cout<<"  "<<kv.first<<": "<<kv.second<<"\n"; }
        for(size_t j=0;j<std::min<size_t>(d.intro_points.size(),5);++j){ std::cout<<"  intro_point: "<<d.intro_points[j]<<"\n"; }
    } else if(args[i]==L"--get" && i+1<args.size()){ std::wstring url=args[i+1]; i+=2; std::string body; if(!HttpGet(url, body)){ std::wcerr<<L"GET failed\n"; return 4; } std::cout<<body<<"\n"; }
      else if(args[i]==L"--post" && i+2<args.size()){ std::wstring url=args[i+1]; std::wstring dataW=args[i+2]; i+=3; std::string data=WideToUtf8(dataW); std::string body; if(!HttpPost(url, data, body)){ std::wcerr<<L"POST failed\n"; return 5; } std::cout<<body<<"\n"; }
      else { std::wcerr<<L"Unknown or incomplete args\n"; PrintUsage(); return 1; } }
    return 0; }

//+------------------------------------------------------------------+
//|                                       EMA_RSI_ATR_Manager.mq5    |
//|   EMA Cross + RSI + ATR with robust risk & margin management     |
//|   One-position-per-symbol, spread/session filters, trailing SL   |
//+------------------------------------------------------------------+
#property strict
#property version   "1.10"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if current margin level below this (%); ignored if <=0 or margin level unavailable
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//----------------------------------------------
// Utility: Parse skip hours string to bool map
//----------------------------------------------
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

//----------------------------------------------
// Utility: Refresh and cache symbol trading info
//----------------------------------------------
bool RefreshSymbolInfo(const string sym)
{
  gPoint = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

//----------------------------------------------
// Utility: Normalize lot volume to broker step
//----------------------------------------------
double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0; // below minimum
  if(v > gMaxVolume) v = gMaxVolume;
  // Normalize to 2 decimals for lots or to digits of step
  int prec = (int)MathMax(0, (int)MathRound(MathLog10(1.0/gVolStep)));
  return NormalizeDouble(v, prec);
}

//----------------------------------------------
// Utility: Normalize price to symbol digits
//----------------------------------------------
double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

//----------------------------------------------
// Utility: Check if any open position exists for this symbol (any magic)
//----------------------------------------------
bool HasAnyPositionOnSymbol(const string sym)
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) == sym)
      return true;
  }
  return false;
}

//----------------------------------------------
// Utility: Find our own (magic) position on this symbol
//----------------------------------------------
bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0;
  typeOut = -1;
  slOut = 0; tpOut=0; volumeOut=0; priceOpenOut=0;
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) continue;

    ticketOut = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut   = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut = PositionGetDouble(POSITION_SL);
    tpOut = PositionGetDouble(POSITION_TP);
    volumeOut = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

//----------------------------------------------
// Utility: Current spread in points
//----------------------------------------------
int CurrentSpreadPoints(const string sym)
{
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick)) return INT_MAX;
  double spread = (tick.ask - tick.bid) / gPoint;
  return (int)MathRound(spread);
}

//----------------------------------------------
// Utility: Check if current UTC hour should be skipped
//----------------------------------------------
bool IsSkipHourUTC()
{
  datetime now = TimeCurrent();
  MqlDateTime t; TimeToStruct(now, t);
  int hourUTC = t.hour; // TimeCurrent is server time; for UTC alignment, servers often in UTC or offset. Adjust if needed.
  if(hourUTC<0 || hourUTC>23) return false;
  return gSkipHour[hourUTC];
}

//----------------------------------------------
// Indicator values on the last closed bar
//----------------------------------------------
bool GetSignalValues(const string sym, ENUM_TIMEFRAMES tf,
                     double &emaFast, double &emaSlow, double &rsi, double &atr,
                     datetime &barTime)
{
  emaFast = emaSlow = rsi = atr = 0.0;
  barTime = 0;

  int bars = Bars(sym, tf);
  if(bars < 200) return false;

  // Last closed bar index = 1
  int shift = 1;
  double vFast[], vSlow[], vRSI[], vATR[];
  if(CopyBuffer(hFastEMA, 0, shift, 2, vFast) != 2) return false;
  if(CopyBuffer(hSlowEMA, 0, shift, 2, vSlow) != 2) return false;
  if(CopyBuffer(hRSI,     0, shift, 1, vRSI)  != 1) return false;
  if(CopyBuffer(hATR,     0, shift, 1, vATR)  != 1) return false;

  emaFast = vFast[1];
  emaSlow = vSlow[1];
  rsi     = vRSI[0];
  atr     = vATR[0];

  datetime times[2];
  if(CopyTime(sym, tf, shift, 1, times) != 1) return false;
  barTime = times[0];
  return true;
}

//----------------------------------------------
// Position sizing: equity risk and margin caps
//----------------------------------------------
double ComputePositionSize(const string sym, bool isBuy, double entry, double sl, double riskPct,
                           double maxFreeMarginUsagePct, double &expectedMargin)
{
  expectedMargin = 0.0;
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);

  double riskAmount = equity * (riskPct/100.0);
  if(riskAmount <= 0) return 0.0;

  double stopDistance = MathAbs(entry - sl);
  if(stopDistance < gPoint) return 0.0;

  // Money per point for 1 lot
  double pointsPerSL = stopDistance / gPoint;
  if(pointsPerSL <= 0) return 0.0;

  // Risk per lot (approx) = points * tickvalue * (point/ticksize)
  double ticksPerPoint = gPoint / gTickSize;
  if(ticksPerPoint <= 0) ticksPerPoint = 1.0;
  double moneyPerPointPerLot = gTickValue * ticksPerPoint;
  if(moneyPerPointPerLot <= 0) return 0.0;

  double lossPerLotAtSL = pointsPerSL * moneyPerPointPerLot;
  if(lossPerLotAtSL <= 0) return 0.0;

  double lotsByRisk = riskAmount / lossPerLotAtSL;

  // Margin cap by free margin
  double maxMarginAllowed = freeMargin * (maxFreeMarginUsagePct/100.0);
  if(maxMarginAllowed <= 0) return 0.0;

  // Estimate margin per 1 lot using OrderCalcMargin
  double marginPerLot = 0.0;
  ENUM_ORDER_TYPE t = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!OrderCalcMargin(t, sym, 1.0, entry, marginPerLot))
  {
    PrintFormat("OrderCalcMargin failed: %d", GetLastError());
    return 0.0;
  }
  if(marginPerLot <= 0) return 0.0;

  double lotsByMargin = maxMarginAllowed / marginPerLot;

  double lots = MathMin(lotsByRisk, lotsByMargin);
  lots = NormalizeVolume(lots);

  // Compute expected margin for chosen lots
  expectedMargin = 0.0;
  if(lots > 0 && !OrderCalcMargin(t, sym, lots, entry, expectedMargin))
  {
    PrintFormat("OrderCalcMargin (lots) failed: %d", GetLastError());
    return 0.0;
  }

  return lots;
}

//----------------------------------------------
// Validate margin level and free margin after hypothetical order
//----------------------------------------------
bool ValidatePostTradeMargin(const string sym, bool isBuy, double lots, double entry,
                             double minMarginLevelPct)
{
  if(lots <= 0) return false;

  double marginNeed = 0.0;
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, lots, entry, marginNeed))
  {
    PrintFormat("OrderCalcMargin validation failed: %d", GetLastError());
    return false;
  }

  double freeMarginNow = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(marginNeed > freeMarginNow)
  {
    PrintFormat("Reject: margin needed %.2f > free margin %.2f", marginNeed, freeMarginNow);
    return false;
  }

  // Approximate post-trade margin level
  double marginNow = AccountInfoDouble(ACCOUNT_MARGIN);
  double equityNow = AccountInfoDouble(ACCOUNT_EQUITY);
  double marginLevelNow = (marginNow>0 ? (equityNow/marginNow)*100.0 : 10000.0);

  double marginLevelPost = ((equityNow) / (marginNow + marginNeed)) * 100.0;

  if(minMarginLevelPct > 0.0)
  {
    if(marginLevelNow < minMarginLevelPct)
    {
      PrintFormat("Reject: current margin level %.2f%% below min %.2f%%", marginLevelNow, minMarginLevelPct);
      return false;
    }
    if(marginLevelPost < minMarginLevelPct)
    {
      PrintFormat("Reject: post-trade margin level %.2f%% would fall below min %.2f%%", marginLevelPost, minMarginLevelPct);
      return false;
    }
  }

  return true;
}

//----------------------------------------------
// Build SL/TP based on ATR and RR
//----------------------------------------------
void BuildStops(bool isBuy, double entry, double atr, double atrSLMult, double rr,
                double &sl, double &tp)
{
  double dist = atr * atrSLMult;
  if(isBuy)
  {
    sl = NormalizePrice(entry - dist);
    tp = NormalizePrice(entry + dist*rr);
  }
  else
  {
    sl = NormalizePrice(entry + dist);
    tp = NormalizePrice(entry - dist*rr);
  }
}

//----------------------------------------------
// Trailing stop and breakeven management
//----------------------------------------------
void ManageTrailing(const string sym)
{
  ulong ticket; long type; double open, sl, tp, vol;
  if(!GetOurPosition(sym, ticket, type, open, sl, tp, vol)) return;

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return;
  double price = (type==POSITION_TYPE_BUY) ? tick.bid : tick.ask;

  // ATR-based trailing
  double atrVals[]; if(CopyBuffer(hATR, 0, 1, 1, atrVals)!=1) return;
  double atr = atrVals[0];
  double trailDist = InpATR_TrailMult * atr;
  if(trailDist < gPoint* (gStopsLevelPoints+2)) trailDist = gPoint*(gStopsLevelPoints+2);

  double newSL = sl;

  // Breakeven logic
  if(InpBreakevenRR > 0.0)
  {
    double riskPerUnit = MathAbs(open - sl);
    if(riskPerUnit > 0)
    {
      double targetBE = open + ((type==POSITION_TYPE_BUY)? +1 : -1) * riskPerUnit * InpBreakevenRR;
      if((type==POSITION_TYPE_BUY && price >= targetBE) || (type==POSITION_TYPE_SELL && price <= targetBE))
      {
        double beSL = open; // move to BE
        if(type==POSITION_TYPE_BUY) newSL = MathMax(sl, beSL);
        else                        newSL = MathMin(sl, beSL);
      }
    }
  }

  if(InpAllowTrailing)
  {
    if(type==POSITION_TYPE_BUY)
    {
      double candidate = price - trailDist;
      if(candidate > newSL) newSL = candidate;
    }
    else
    {
      double candidate = price + trailDist;
      if(candidate < newSL || newSL==0.0) newSL = candidate;
    }
  }

  newSL = NormalizePrice(newSL);

  // Respect stop levels and freeze levels
  if(gFreezeLevelPoints>0)
  {
    // If within freeze level from current price, skip modification to avoid rejection
    double distPts = MathAbs((price - newSL)/gPoint);
    if(distPts < gFreezeLevelPoints+1) return;
  }

  if(newSL>0 && MathAbs(newSL - sl) >= gPoint)
  {
    trade.SetExpertMagicNumber(InpMagicNumber);
    trade.PositionSelect(sym);
    if(!trade.PositionModify(newSL, tp))
    {
      PrintFormat("PositionModify failed: %d", trade.ResultRetcode());
    }
  }
}

//----------------------------------------------
// Order send wrapper with detailed logging
//----------------------------------------------
bool OpenPosition(const string sym, bool isBuy, double lots, double sl, double tp, int slippagePts)
{
  trade.SetExpertMagicNumber(InpMagicNumber);
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return false;
  double price = isBuy ? tick.ask : tick.bid;

  trade.SetDeviationInPoints(slippagePts);

  bool ok = isBuy ? trade.Buy(lots, sym, price, sl, tp) : trade.Sell(lots, sym, price, sl, tp);
  if(!ok)
  {
    PrintFormat("Order send failed: retcode=%d reason=%s", trade.ResultRetcode(), trade.ResultRetcodeDescription());
    return false;
  }
  return true;
}

//----------------------------------------------
// OnInit: create indicators and cache symbol info
//----------------------------------------------
int OnInit()
{
  string sym = _Symbol;
  if(!RefreshSymbolInfo(sym))
  {
    Print("Init failed: symbol info invalid");
    return INIT_FAILED;
  }

  hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("Init failed: indicator handle invalid");
    return INIT_FAILED;
  }

  ArraySetAsSeries(gSkipHour, false);
  ParseSkipHours(InpSkipHoursUTC);

  // Prime last closed bar time
  datetime times[2];
  if(CopyTime(sym, InpTimeframe, 1, 1, times)==1)
    gLastClosedBarTime = times[0];

  Print("EA initialized successfully.");
  return INIT_SUCCEEDED;
}

//----------------------------------------------
// OnDeinit
//----------------------------------------------
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI    !=INVALID_HANDLE) IndicatorRelease(hRSI);
  if(hATR    !=INVALID_HANDLE) IndicatorRelease(hATR);
}

//----------------------------------------------
// OnTick: signal, risk/margin checks, trade management
//----------------------------------------------
void OnTick()
{
  string sym = _Symbol;

  // Spread/session filters
  if(IsSkipHourUTC()) return;
  if(CurrentSpreadPoints(sym) > InpMaxSpreadPoints) return;

  // One-position-per-symbol (any position blocks new entries)
  if(HasAnyPositionOnSymbol(sym))
  {
    // Manage trailing for our own position only
    ManageTrailing(sym);
    return;
  }

  // Process only on new closed bar
  datetime barTime;
  double emaFast, emaSlow, rsi, atr;
  if(!GetSignalValues(sym, InpTimeframe, emaFast, emaSlow, rsi, atr, barTime)) return;
  if(barTime == 0 || barTime == gLastClosedBarTime) return;
  gLastClosedBarTime = barTime;

  // ATR filter
  if(InpATR_MinFilter > 0.0 && atr < InpATR_MinFilter) return;

  // Generate signals: EMA cross and RSI confirmation
  bool buySignal = (emaFast > emaSlow) && (rsi >= InpRSI_Buy);
  bool sellSignal= (emaFast < emaSlow) && (rsi <= InpRSI_Sell);
  if(!(buySignal || sellSignal)) return;

  // Prices and stops
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return;
  bool isBuy = buySignal && !sellSignal;
  if(!isBuy && !sellSignal) return;

  double entry = isBuy ? tick.ask : tick.bid;
  double sl=0.0, tp=0.0;
  BuildStops(isBuy, entry, atr, InpATR_SL_Mult, InpRR, sl, tp);

  // Respect broker stop levels
  int minStopPts = gStopsLevelPoints + 2; // add small buffer
  if(minStopPts>0)
  {
    double minStopDist = minStopPts * gPoint;
    if(isBuy)
    {
      if(entry - sl < minStopDist) sl = NormalizePrice(entry - minStopDist);
      if(tp - entry < minStopDist) tp = NormalizePrice(entry + minStopDist);
    }
    else
    {
      if(sl - entry < minStopDist) sl = NormalizePrice(entry + minStopDist);
      if(entry - tp < minStopDist) tp = NormalizePrice(entry - minStopDist);
    }
  }

  // Compute size based on equity risk and margin caps
  double expectedMargin = 0.0;
  double lots = ComputePositionSize(sym, isBuy, entry, sl, InpRiskPerTradePct, InpMaxFreeMarginUsagePct, expectedMargin);
  if(lots <= 0.0)
  {
    Print("Sizing rejected: zero lots (risk/margin constraints)");
    return;
  }

  // Validate margin level and free margin post trade
  if(!ValidatePostTradeMargin(sym, isBuy, lots, entry, InpMinMarginLevelPct))
    return;

  // Final spread check right before sending
  if(CurrentSpreadPoints(sym) > InpMaxSpreadPoints)
  {
    Print("Spread widened, aborting entry");
    return;
  }

  // Send order
  if(!OpenPosition(sym, isBuy, lots, sl, tp, InpSlippagePoints))
    return;

  // After open, manage initial trailing if enabled
  ManageTrailing(sym);
}

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|       EMA Cross + RSI + ATR with robust risk & margin controls   |
//|       One-position-per-symbol, spread/session filters, trailing  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.20"
#property description "EMA Cross + RSI + ATR strategy with complete trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity to risk per trade
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if margin level below this (%); ignored if <=0 or if account doesn't report level
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastClosedBarTime = 0;

// Symbol parameters cache
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC)
bool    gSkipHour[24];

//========================
// Forward declarations
//========================
void   ParseSkipHours(const string hours_csv);
bool   RefreshSymbolInfo(const string sym);
double NormalizeVolume(double vol);
double NormalizePrice(double price);
bool   HasAnyPositionOnSymbol(const string sym);
bool   GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut);
bool   BuildSignals(const string sym, ENUM_TIMEFRAMES tf, bool &buySignal, bool &sellSignal, double &atr);
bool   AllowedByFilters(const string sym, double &spreadPoints);
bool   ComputeSLTP(const string sym, bool isBuy, double atr, double &sl, double &tp);
bool   ComputeRiskVolume(const string sym, bool isBuy, double sl, double &vol, double &estMargin);
bool   CheckAccountMarginRoom(double estMargin);
void   ManageTrailingAndBE(const string sym, double atr);
void   LogLastError(const string context);

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
{
  string sym = _Symbol;
  if(!RefreshSymbolInfo(sym))
  {
    Print("OnInit: Failed to refresh symbol info.");
    return(INIT_FAILED);
  }

  // Create indicators
  hFastEMA = iMA(sym, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(sym, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(sym, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(sym, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("OnInit: Indicator handle creation failed.");
    return(INIT_FAILED);
  }

  // Ensure data is loaded
  if(!ChartSetSymbolPeriod(0, sym, (int)Period()))
    Print("OnInit: ChartSetSymbolPeriod warning: ", GetLastError());

  // Parse session skip hours
  ParseSkipHours(InpSkipHoursUTC);

  gLastClosedBarTime = 0;

  // Trade settings
  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints((int)InpSlippagePoints);

  return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
  string sym = _Symbol;

  // Only process once per new closed bar to avoid signal duplication
  MqlRates rates[];
  if(CopyRates(sym, InpTimeframe, 0, 3, rates) < 3)
    return;
  ArraySetAsSeries(rates, true);
  datetime lastClosedBar = rates[1].time; // bar index 1 is last closed
  bool isNewBar = (lastClosedBar != gLastClosedBarTime);

  // Always manage trailing on each tick for open position
  double atr_val = 0.0;
  bool buySig=false, sellSig=false;

  // Manage existing position (trailing/BE)
  if(hATR!=INVALID_HANDLE)
  {
    double atrBuff[3];
    if(CopyBuffer(hATR, 0, 0, 3, atrBuff) >= 2)
      atr_val = atrBuff[1];
  }
  if(atr_val>0.0 && InpAllowTrailing)
    ManageTrailingAndBE(sym, atr_val);

  if(!isNewBar)
    return;

  gLastClosedBarTime = lastClosedBar;

  // Enforce one-position-per-symbol strictly
  if(HasAnyPositionOnSymbol(sym))
  {
    // Already in a position, do not open new ones
    return;
  }

  // Check entry filters (session, spread, trade context)
  double spreadPts = 0.0;
  if(!AllowedByFilters(sym, spreadPts))
    return;

  // Build signals on the just-closed bar
  double atrSignal = 0.0;
  if(!BuildSignals(sym, InpTimeframe, buySig, sellSig, atrSignal))
    return;

  if(InpATR_MinFilter>0.0 && atrSignal < InpATR_MinFilter)
    return;

  if(!(buySig || sellSig))
    return;

  // Compute SL/TP from ATR
  double sl=0.0, tp=0.0;
  if(!ComputeSLTP(sym, buySig, atrSignal, sl, tp))
    return;

  // Compute risk-based volume and estimate margin
  double vol=0.0, estMargin=0.0;
  if(!ComputeRiskVolume(sym, buySig, sl, vol, estMargin))
    return;
  if(vol<=0.0)
  {
    Print("OnTick: Computed volume is zero after normalization.");
    return;
  }

  // Final margin room check
  if(!CheckAccountMarginRoom(estMargin))
    return;

  // Place order
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick))
  {
    LogLastError("SymbolInfoTick failed");
    return;
  }

  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints((int)InpSlippagePoints);

  bool result=false;
  if(buySig)
  {
    double price = NormalizePrice(tick.ask);
    result = trade.Buy(vol, sym, price, sl, tp, "EMA/RSI Buy");
  }
  else if(sellSig)
  {
    double price = NormalizePrice(tick.bid);
    result = trade.Sell(vol, sym, price, sl, tp, "EMA/RSI Sell");
  }

  if(!result)
  {
    LogLastError("Order placement failed");
    return;
  }
}

//+------------------------------------------------------------------+
//| Utilities                                                        |
//+------------------------------------------------------------------+
void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gPoint = SymbolInfoDouble(sym, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  gTickValue = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  gMaxVolume = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  gVolStep = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(sym, SYMBOL_TRADE_FREEZE_LEVEL);

  if(gPoint<=0 || gTickSize<=0 || gTickValue<=0 || gMinVolume<=0 || gVolStep<=0)
  {
    PrintFormat("Symbol info invalid: point=%.10f ticksize=%.10f tickvalue=%.10f minvol=%.2f volstep=%.2f",
                gPoint, gTickSize, gTickValue, gMinVolume, gVolStep);
    return false;
  }
  return true;
}

double NormalizeVolume(double vol)
{
  if(vol<=0) return 0.0;
  double steps = MathFloor(vol / gVolStep + 1e-8);
  double v = steps * gVolStep;
  if(v < gMinVolume) v = 0.0;
  if(v > gMaxVolume) v = gMaxVolume;
  // round to 8 decimals to respect symbols with small step
  return NormalizeDouble(v, 8);
}

double NormalizePrice(double price)
{
  return NormalizeDouble(price, gDigits);
}

bool HasAnyPositionOnSymbol(const string sym)
{
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i))
      continue;
    string psym = PositionGetString(POSITION_SYMBOL);
    if(psym == sym)
      return true;
  }
  return false;
}

bool GetOurPosition(const string sym, ulong &ticketOut, long &typeOut, double &priceOpenOut, double &slOut, double &tpOut, double &volumeOut)
{
  ticketOut = 0; typeOut=-1; priceOpenOut=0; slOut=0; tpOut=0; volumeOut=0;
  int total = PositionsTotal();
  for(int i=0;i<total;i++)
  {
    if(!PositionSelectByIndex(i)) continue;
    if(PositionGetString(POSITION_SYMBOL) != sym) continue;
    long mg = (long)PositionGetInteger(POSITION_MAGIC);
    if((ulong)mg != InpMagicNumber) continue;

    ticketOut     = (ulong)PositionGetInteger(POSITION_TICKET);
    typeOut       = (long)PositionGetInteger(POSITION_TYPE);
    priceOpenOut  = PositionGetDouble(POSITION_PRICE_OPEN);
    slOut         = PositionGetDouble(POSITION_SL);
    tpOut         = PositionGetDouble(POSITION_TP);
    volumeOut     = PositionGetDouble(POSITION_VOLUME);
    return true;
  }
  return false;
}

bool BuildSignals(const string sym, ENUM_TIMEFRAMES tf, bool &buySignal, bool &sellSignal, double &atr)
{
  buySignal=false; sellSignal=false; atr=0.0;
  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
    return false;

  double fast[3], slow[3], rsi[3], atrb[3];
  int need=3;
  if(CopyBuffer(hFastEMA,0,0,need,fast) < 2) return false;
  if(CopyBuffer(hSlowEMA,0,0,need,slow) < 2) return false;
  if(CopyBuffer(hRSI,    0,0,need,rsi)  < 2) return false;
  if(CopyBuffer(hATR,    0,0,need,atrb) < 2) return false;

  // Use bar[1] (last closed) and bar[2] for cross confirmation
  double f1=fast[1], f2=fast[2];
  double s1=slow[1], s2=slow[2];
  double r1=rsi[1];
  atr = atrb[1];

  bool emaBullCross = (f2 <= s2 && f1 > s1);
  bool emaBearCross = (f2 >= s2 && f1 < s1);

  if(emaBullCross && r1 >= InpRSI_Buy)
    buySignal = true;
  if(emaBearCross && r1 <= InpRSI_Sell)
    sellSignal = true;

  return true;
}

bool AllowedByFilters(const string sym, double &spreadPoints)
{
  spreadPoints = 0.0;
  // Session hour filter (UTC)
  datetime now = TimeCurrent();
  MqlDateTime dt; TimeToStruct(now, dt);
  int utcHour = dt.hour;
  if(utcHour>=0 && utcHour<24 && gSkipHour[utcHour])
    return false;

  // Spread filter
  MqlTick tick;
  if(!SymbolInfoTick(sym, tick))
  {
    LogLastError("AllowedByFilters: SymbolInfoTick failed");
    return false;
  }
  spreadPoints = (tick.ask - tick.bid)/gPoint;
  if(InpMaxSpreadPoints>0 && spreadPoints > InpMaxSpreadPoints)
    return false;

  // Trading allowed check
  long trade_mode = (long)SymbolInfoInteger(sym, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED)
    return false;

  // Freeze/Stops level awareness (no explicit action here, but SL/TP will respect)
  return true;
}

bool ComputeSLTP(const string sym, bool isBuy, double atr, double &sl, double &tp)
{
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) { LogLastError("ComputeSLTP: SymbolInfoTick failed"); return false; }
  double price = isBuy ? tick.ask : tick.bid;
  double sl_dist = atr * InpATR_SL_Mult;
  if(sl_dist <= 0.0) return false;

  double sl_raw = isBuy ? price - sl_dist : price + sl_dist;
  double tp_dist = InpRR * sl_dist;
  double tp_raw = isBuy ? price + tp_dist : price - tp_dist;

  sl = NormalizePrice(sl_raw);
  tp = NormalizePrice(tp_raw);

  // Respect stops level
  int minStops = gStopsLevelPoints;
  if(minStops>0)
  {
    if(isBuy)
    {
      double minSL = NormalizePrice(price - minStops*gPoint);
      if(sl > minSL) sl = minSL;
      double minTP = NormalizePrice(price + minStops*gPoint);
      if(tp < minTP) tp = minTP;
    }
    else
    {
      double minSL = NormalizePrice(price + minStops*gPoint);
      if(sl < minSL) sl = minSL;
      double minTP = NormalizePrice(price - minStops*gPoint);
      if(tp > minTP) tp = minTP;
    }
  }
  return true;
}

bool ComputeRiskVolume(const string sym, bool isBuy, double sl, double &vol, double &estMargin)
{
  vol = 0.0; estMargin = 0.0;

  // Account info
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);

  if(equity<=0.0 || freeMargin<0.0)
  {
    Print("ComputeRiskVolume: Invalid account equity/free margin.");
    return false;
  }

  // Market price
  MqlTick tick; if(!SymbolInfoTick(sym, tick)) { LogLastError("ComputeRiskVolume: SymbolInfoTick failed"); return false; }
  double price = isBuy ? tick.ask : tick.bid;

  // Risk amount in account currency
  double riskAmt = equity * (InpRiskPerTradePct/100.0);
  if(riskAmt <= 0.0)
  {
    Print("ComputeRiskVolume: Calculated risk amount <= 0");
    return false;
  }

  // Distance to SL
  double slDistance = MathAbs(price - sl);
  if(slDistance <= 0)
  {
    Print("ComputeRiskVolume: SL distance is zero");
    return false;
  }

  // Value per point per lot
  double contractSize = SymbolInfoDouble(sym, SYMBOL_TRADE_CONTRACT_SIZE);
  if(contractSize<=0) contractSize = 100000.0; // fallback typical FX

  double tickVal = gTickValue;
  double pointsPerTick = gTickSize / gPoint;
  if(pointsPerTick<=0) pointsPerTick = 1.0;
  double valuePerPointPerLot = (tickVal / pointsPerTick);

  double pointsToSL = slDistance / gPoint;
  if(pointsToSL<=0)
  {
    Print("ComputeRiskVolume: pointsToSL <= 0");
    return false;
  }

  double volByRisk = riskAmt / (pointsToSL * valuePerPointPerLot);
  vol = NormalizeVolume(volByRisk);
  if(vol<=0.0)
  {
    Print("ComputeRiskVolume: Volume after normalization <= 0");
    return false;
  }

  // Estimate margin via OrderCalcMargin
  double priceForMargin = price;
  ENUM_ORDER_TYPE t = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!OrderCalcMargin(t, sym, vol, priceForMargin, estMargin))
  {
    LogLastError("ComputeRiskVolume: OrderCalcMargin failed");
    return false;
  }

  // Per-trade margin cap vs free margin
  double cap = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  if(cap>0.0 && estMargin > cap)
  {
    // scale volume down proportionally
    double scale = cap / estMargin;
    double v2 = NormalizeVolume(vol * scale);
    if(v2 <= 0.0)
    {
      PrintFormat("ComputeRiskVolume: estMargin %.2f exceeds cap %.2f and scaled volume <= 0", estMargin, cap);
      return false;
    }
    vol = v2;
    if(!OrderCalcMargin(t, sym, vol, priceForMargin, estMargin))
    {
      LogLastError("ComputeRiskVolume: OrderCalcMargin failed after scale");
      return false;
    }
  }

  // Ensure free margin can cover estimated margin
  if(estMargin > freeMargin)
  {
    PrintFormat("ComputeRiskVolume: estMargin %.2f > freeMargin %.2f", estMargin, freeMargin);
    return false;
  }

  // Margin level check (if available and threshold > 0)
  double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
  if(InpMinMarginLevelPct>0.0 && marginLevel>0.0 && marginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("ComputeRiskVolume: Margin level %.2f%% below minimum %.2f%%", marginLevel, InpMinMarginLevelPct);
    return false;
  }

  return true;
}

bool CheckAccountMarginRoom(double estMargin)
{
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(freeMargin < estMargin)
  {
    PrintFormat("CheckAccountMarginRoom: freeMargin %.2f < estMargin %.2f", freeMargin, estMargin);
    return false;
  }
  // Post-trade projected margin level sanity (best-effort)
  double eq = AccountInfoDouble(ACCOUNT_EQUITY);
  double usedMargin = AccountInfoDouble(ACCOUNT_MARGIN);
  double projMarginLevel = 0.0;
  if(usedMargin + estMargin > 0.0)
    projMarginLevel = (eq / (usedMargin + estMargin)) * 100.0;
  if(InpMinMarginLevelPct>0.0 && projMarginLevel>0.0 && projMarginLevel < InpMinMarginLevelPct)
  {
    PrintFormat("CheckAccountMarginRoom: projected margin level %.2f%% below minimum %.2f%%", projMarginLevel, InpMinMarginLevelPct);
    return false;
  }
  return true;
}

void ManageTrailingAndBE(const string sym, double atr)
{
  ulong ticket; long type; double openPrice, sl, tp, vol;
  if(!GetOurPosition(sym, ticket, type, openPrice, sl, tp, vol))
    return;

  MqlTick tick; if(!SymbolInfoTick(sym, tick)) return;

  double trailDist = InpATR_TrailMult * atr;
  if(trailDist<=0.0) return;

  double newSL = sl;
  if(type == POSITION_TYPE_BUY)
  {
    double bePrice = openPrice; // BE level
    if(InpBreakevenRR>0)
    {
      double beShift = (InpBreakevenRR * (openPrice - sl));
      bePrice = openPrice + beShift;
    }

    double trailLevel = tick.bid - trailDist;
    if(InpBreakevenRR>0) trailLevel = MathMax(trailLevel, bePrice);

    if(sl < trailLevel)
      newSL = NormalizePrice(trailLevel);
  }
  else if(type == POSITION_TYPE_SELL)
  {
    double bePrice = openPrice;
    if(InpBreakevenRR>0)
    {
      double beShift = (InpBreakevenRR * (sl - openPrice));
      bePrice = openPrice - beShift;
    }

    double trailLevel = tick.ask + trailDist;
    if(InpBreakevenRR>0) trailLevel = MathMin(trailLevel, bePrice);

    if(sl == 0.0 || sl > trailLevel)
      newSL = NormalizePrice(trailLevel);
  }

  if(newSL != sl)
  {
    trade.SetExpertMagicNumber((long)InpMagicNumber);
    if(!trade.PositionModify(sym, newSL, tp))
      LogLastError("ManageTrailingAndBE: PositionModify failed");
  }
}

void LogLastError(const string context)
{
  int err = GetLastError();
  if(err!=0)
    PrintFormat("%s. Error %d: %s", context, err, ErrorDescription(err));
}

//+------------------------------------------------------------------+
//| Notes and guidance                                               |
//+------------------------------------------------------------------+
// Key components:
// - EMA cross with RSI filter on closed bars to avoid intrabar noise.
// - Strict one-position-per-symbol rule via HasAnyPositionOnSymbol().
// - SL/TP derived from ATR with RR multiplier; respects broker stop levels.
// - Trailing stop and optional breakeven logic using ATR distance.
// - Margin/risk: equity-based risk sizing, OrderCalcMargin for per-trade
//   margin estimate; free-margin and margin-level validations; per-trade
//   margin usage cap; projected post-trade margin level sanity check.
// - Error handling via LogLastError and PrintFormat messages.
// Testing & deployment:
// - Forward-test on demo first; optimize inputs (EMA/RSI/ATR/RR) per symbol.
// - Validate broker stops/freeze levels; widen SL/TP if needed.
// - Consider VPS for stability; enable journal logging.
// - Realistic expectations: compounding from $10 to $10,000 involves high risk; 
//   this EA focuses on disciplined risk and margin controls, not guaranteed returns.

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|  EMA Cross + RSI + ATR with robust risk & margin controls        |
//|  One-position-per-symbol, spread/session filters, trailing stop  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.30"
#property description "EMA Cross + RSI + ATR strategy with full trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity risk per trade (e.g., 0.5 = 0.5%)
input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if margin level would fall below this (%); ignored if <=0
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
