//------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------
void LogLastError(const string context)
{
  int err = GetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = StringTrim(hours_csv);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = StringTrim(parts[i]);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }
  return true;
}

bool EnsureIndicators()
{
  if(hFastEMA==INVALID_HANDLE)
    hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hSlowEMA==INVALID_HANDLE)
    hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hRSI==INVALID_HANDLE)
    hRSI = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  if(hATR==INVALID_HANDLE)
    hATR = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    LogLastError("Indicator handle creation failed");
    return false;
  }
  return true;
}

bool CopyLatest(const int handle, const int count, double &buf[])
{
  ArraySetAsSeries(buf,true);
  if(CopyBuffer(handle,0,0,count,buf)<count)
  {
    LogLastError("CopyBuffer failed");
    return false;
  }
  return true;
}

bool IsSessionAllowed()
{
  datetime t = TimeCurrent();
  MqlDateTime mt;
  TimeToStruct(t, mt);
  // Server time is often close to UTC; for strict UTC control, assume server time as UTC.
  int hour = mt.hour;
  if(hour<0 || hour>23) return true;
  return !gSkipHour[hour];
}

bool OnePositionPerSymbol()
{
  for(int i=0;i<PositionsTotal();++i)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    string sym = PositionGetString(POSITION_SYMBOL);
    ulong mg = (ulong)PositionGetInteger(POSITION_MAGIC);
    if(sym==gSymbol && mg==InpMagicNumber)
      return false; // already have a position
  }
  return true;
}

int CurrentPositionDirection(int &index_out)
{
  index_out = -1;
  for(int i=0;i<PositionsTotal();++i)
  {
    if(!PositionSelectByIndex(i)) continue;
    string sym = PositionGetString(POSITION_SYMBOL);
    ulong mg = (ulong)PositionGetInteger(POSITION_MAGIC);
    if(sym==gSymbol && mg==InpMagicNumber)
    {
      index_out = i;
      long type = PositionGetInteger(POSITION_TYPE);
      return (type==POSITION_TYPE_BUY)?1:(type==POSITION_TYPE_SELL?-1:0);
    }
  }
  return 0;
}

// Rounds volume to broker constraints
double NormalizeVolume(double vol)
{
  if(vol<gMinVolume) vol=gMinVolume;
  if(vol>gMaxVolume) vol=gMaxVolume;
  if(gVolStep>0)
    vol = MathFloor((vol + 1e-12)/gVolStep)*gVolStep;
  return NormalizeDouble(vol, (int)MathMax(0,MathRound(-MathLog10(gVolStep>0?gVolStep:0.01))));
}

// Compute trade parameters and lot size using margin- and equity-based constraints.
bool ComputeOrderParams(const bool isBuy,
                        double &volume,
                        double &sl_price,
                        double &tp_price,
                        double &atr_val,
                        string &reason)
{
  reason = "";
  MqlTick tick;
  if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick failed"); reason="tick"; return false; }

  // Prices
  double price_open = isBuy ? tick.ask : tick.bid;

  // Indicators
  double atrbuf[3];
  if(!CopyLatest(hATR, 3, atrbuf)) { reason="atr copy"; return false; }
  atr_val = atrbuf[0];

  if(InpATR_MinFilter>0 && atr_val < InpATR_MinFilter)
  { reason = "ATR below minimum"; return false; }

  double sl_distance = InpATR_SL_Mult * atr_val;
  if(sl_distance <= 0 || !MathIsValidNumber(sl_distance)) { reason="invalid SL distance"; return false; }

  // Respect stops/freeze levels
  double min_stop = (double)gStopsLevelPoints * gPoint;
  if(sl_distance < min_stop) sl_distance = min_stop;

  // SL/TP calculation
  if(isBuy)
  {
    sl_price = price_open - sl_distance;
    double tp_distance = InpRR * sl_distance;
    tp_price = price_open + tp_distance;
  }
  else
  {
    sl_price = price_open + sl_distance;
    double tp_distance = InpRR * sl_distance;
    tp_price = price_open - tp_distance;
  }

  // Ensure SL/TP not within freeze level
  double freeze = (double)gFreezeLevelPoints * gPoint;
  if(isBuy)
  {
    if((price_open - sl_price) < MathMax(min_stop, freeze)) sl_price = price_open - MathMax(min_stop, freeze);
    if((tp_price - price_open) < MathMax(min_stop, freeze)) tp_price = price_open + MathMax(min_stop, freeze);
  }
  else
  {
    if((sl_price - price_open) < MathMax(min_stop, freeze)) sl_price = price_open + MathMax(min_stop, freeze);
    if((price_open - tp_price) < MathMax(min_stop, freeze)) tp_price = price_open - MathMax(min_stop, freeze);
  }

  // Risk-based position sizing using equity and OrderCalcMargin
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double margin_level = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL); // percent, may be 0 if not defined

  if(equity<=0 || free_margin<=0) { reason="insufficient equity/free margin"; return false; }

  double risk_cash = equity * (InpRiskPerTradePct/100.0);
  if(risk_cash <= 0) { reason="risk 0"; return false; }

  // Approximate pip value per lot using tick value/size
  if(gTickSize<=0 || gTickValue<=0) { reason="tick params"; return false; }

  // Price unit per tick = gTickSize; value per tick per 1 lot = gTickValue.
  // SL distance in price units -> ticks = sl_distance / gTickSize
  double sl_ticks = sl_distance / gTickSize;
  if(sl_ticks<=0) { reason="sl_ticks"; return false; }

  // Risk per 1 lot approximately: sl_ticks * gTickValue
  double risk_per_lot = sl_ticks * gTickValue;
  if(risk_per_lot<=0) { reason="risk_per_lot"; return false; }

  double vol_by_risk = risk_cash / risk_per_lot;
  if(vol_by_risk<=0) { reason="vol_by_risk"; return false; }

  // Now check margin requirement via OrderCalcMargin and apply per-trade cap vs free margin
  // We'll find the maximal volume that satisfies both risk and margin caps.
  // Start with risk-based volume, then limit by margin caps.
  double test_vol = vol_by_risk;
  test_vol = MathMin(test_vol, gMaxVolume);
  test_vol = MathMax(test_vol, gMinVolume);

  // Binary search down to find a volume that passes OrderCalcMargin and free-margin cap
  double fm_cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(fm_cap<=0) { reason="fm cap 0"; return false; }

  double lo = gMinVolume, hi = MathMin(test_vol, gMaxVolume);
  if(hi < lo) hi = lo;

  double chosen = 0.0;
  for(int it=0; it<25; ++it)
  {
    double mid = (lo+hi)*0.5;
    double margin_req = 0.0;
    if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, mid, price_open, margin_req))
    {
      LogLastError("OrderCalcMargin failed");
      reason="OrderCalcMargin";
      return false;
    }

    // Check free margin cap and minimal remaining margin level, if applicable
    bool within_cap = (margin_req <= fm_cap);

    // Predict post-trade margin level if broker reports it: MarginLevel% = Equity / Margin * 100
    bool ml_ok = true;
    if(InpMinMarginLevelPct>0.0)
    {
      double current_margin = AccountInfoDouble(ACCOUNT_MARGIN);
      double projected_margin = current_margin + margin_req;
      if(projected_margin>0)
      {
        double projected_level = (equity / projected_margin) * 100.0;
        ml_ok = (projected_level >= InpMinMarginLevelPct);
      }
    }

    if(within_cap && ml_ok)
    {
      chosen = mid;
      lo = mid + gVolStep;
    }
    else
    {
      hi = mid - gVolStep;
      if(hi < gMinVolume) hi = gMinVolume;
    }

    if(hi - lo < gVolStep) break;
  }

  if(chosen < gMinVolume)
  {
    reason = "No volume satisfies margin caps";
    return false;
  }

  volume = NormalizeVolume(chosen);
  if(volume < gMinVolume - 1e-12) { reason="normalized volume too small"; return false; }

  // Final margin check with chosen volume
  double final_margin = 0.0;
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, volume, price_open, final_margin))
  { LogLastError("Final OrderCalcMargin failed"); reason="final margin"; return false; }
  if(final_margin > fm_cap + 1e-6)
  { reason = "final margin exceeds cap"; return false; }

  // Free margin after trade must remain positive
  if(free_margin - final_margin <= 0)
  { reason = "not enough free margin"; return false; }

  // Margin level projection check again
  if(InpMinMarginLevelPct>0.0)
  {
    double current_margin = AccountInfoDouble(ACCOUNT_MARGIN);
    double projected_margin = current_margin + final_margin;
    if(projected_margin>0)
    {
      double projected_level = (equity / projected_margin) * 100.0;
      if(projected_level < InpMinMarginLevelPct)
      { reason = "projected margin level too low"; return false; }
    }
  }

  return true;
}

bool CheckSpreadOK()
{
  MqlTick tick; if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick spread"); return false; }
  double spread_points = (tick.ask - tick.bid) / gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

bool GetSignal(bool &buy, bool &sell)
{
  buy=false; sell=false;
  // Need at least 2 bars for crossover logic
  double f[3], s[3], r[3];
  if(!CopyLatest(hFastEMA, 3, f)) return false;
  if(!CopyLatest(hSlowEMA, 3, s)) return false;
  if(!CopyLatest(hRSI,   3, r))   return false;

  // Use previous closed bar for signal confirmation
  double f_prev = f[1];
  double s_prev = s[1];
  double r_prev = r[1];

  // Crossover with RSI filter
  if(f_prev > s_prev && r_prev >= InpRSI_Buy)
    buy = true;
  else if(f_prev < s_prev && r_prev <= InpRSI_Sell)
    sell = true;

  return true;
}

void ApplyTrailingStop()
{
  if(!InpAllowTrailing) return;

  int idx;
  int dir = CurrentPositionDirection(idx);
  if(dir==0) return;

  if(!PositionSelect(gSymbol)) return;

  double price_open   = PositionGetDouble(POSITION_PRICE_OPEN);
  double price_sl     = PositionGetDouble(POSITION_SL);
  double price_tp     = PositionGetDouble(POSITION_TP);
  double volume       = PositionGetDouble(POSITION_VOLUME);
  long   type         = (long)PositionGetInteger(POSITION_TYPE);

  MqlTick tick; if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("tick trailing"); return; }

  // ATR-based trailing distance
  double atrbuf[2];
  if(!CopyLatest(hATR, 2, atrbuf)) return;
  double trail_dist = InpATR_TrailMult * atrbuf[0];
  double min_stop   = (double)gStopsLevelPoints * gPoint;
  double freeze     = (double)gFreezeLevelPoints * gPoint;
  trail_dist = MathMax(trail_dist, MathMax(min_stop, freeze));

  double new_sl = price_sl;

  if(type==POSITION_TYPE_BUY)
  {
    double candidate = tick.bid - trail_dist;
    // Breakeven logic
    if(InpBreakevenRR>0)
    {
      double sl_base = price_open;
      double be_dist = trail_dist * InpBreakevenRR; // using RR vs SL distance
      if(tick.bid - price_open >= be_dist)
        candidate = MathMax(candidate, price_open);
    }
    if(price_sl==0.0 || candidate > price_sl + gPoint*0.5)
      new_sl = candidate;
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double candidate = tick.ask + trail_dist;
    if(InpBreakevenRR>0)
    {
      double be_dist = trail_dist * InpBreakevenRR;
      if(price_open - tick.ask >= be_dist)
        candidate = MathMin(candidate, price_open);
    }
    if(price_sl==0.0 || candidate < price_sl - gPoint*0.5)
      new_sl = candidate;
  }

  if(new_sl!=price_sl)
  {
    trade.SetAsyncMode(false);
    if(!trade.PositionModify(gSymbol, new_sl, price_tp))
      LogLastError("PositionModify (trailing) failed");
  }
}

bool PlaceOrder(const bool isBuy, const double volume, const double sl, const double tp)
{
  MqlTick tick; if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("tick placeorder"); return false; }
  double price = isBuy ? tick.ask : tick.bid;

  trade.SetAsyncMode(false);
  trade.SetExpertMagicNumber(InpMagicNumber);

  bool ok=false;
  if(isBuy)
    ok = trade.Buy(volume, gSymbol, price, sl, tp, "EMA_RSI_ATR Buy");
  else
    ok = trade.Sell(volume, gSymbol, price, sl, tp, "EMA_RSI_ATR Sell");

  if(!ok)
    LogLastError("OrderSend failed");

  return ok;
}

//========================
// Standard Events
//========================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol)) return INIT_FAILED;
  ParseSkipHours(InpSkipHoursUTC);

  if(!EnsureIndicators()) return INIT_FAILED;

  // Preload indicator buffers
  double tmp[3];
  if(!CopyLatest(hFastEMA,3,tmp)) return INIT_FAILED;
  if(!CopyLatest(hSlowEMA,3,tmp)) return INIT_FAILED;
  if(!CopyLatest(hRSI,   3,tmp)) return INIT_FAILED;
  if(!CopyLatest(hATR,   3,tmp)) return INIT_FAILED;

  Print("EA initialized on ", gSymbol);
  return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(!RefreshSymbolInfo(_Symbol)) return;

  // One position per symbol rule
  if(!OnePositionPerSymbol()) { ApplyTrailingStop(); return; }

  // Session filter
  if(!IsSessionAllowed()) return;

  // Spread filter
  if(!CheckSpreadOK()) return;

  if(!EnsureIndicators()) return;

  // Signal
  bool buy=false, sell=false;
  if(!GetSignal(buy, sell)) return;

  // Only act on a new bar to avoid duplicates
  datetime times[2];
  ArraySetAsSeries(times,true);
  if(CopyTime(gSymbol, InpTimeframe, 0, 2, times)<2) return;
  if(times[1]==0) return;
  if(gLastSignalBarTime == times[1]) { ApplyTrailingStop(); return; }

  // Compute order params and risk/margin sizing
  double vol=0.0, sl=0.0, tp=0.0, atr=0.0; string reason="";

  if(buy)
  {
    if(ComputeOrderParams(true, vol, sl, tp, atr, reason))
    {
      if(PlaceOrder(true, vol, sl, tp))
        gLastSignalBarTime = times[1];
    }
    else
    {
      PrintFormat("Buy skipped: %s", reason);
    }
  }
  else if(sell)
  {
    if(ComputeOrderParams(false, vol, sl, tp, atr, reason))
    {
      if(PlaceOrder(false, vol, sl, tp))
        gLastSignalBarTime = times[1];
    }
    else
    {
      PrintFormat("Sell skipped: %s", reason);
    }
  }

  // Trailing for any open position (should not be any before order due to one-position rule, but safe)
  ApplyTrailingStop();
}

