input double          InpMaxFreeMarginUsagePct     = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct         = 500.0; // Do not open if projected margin level < this (%); ignored if <=0
input ulong           InpMagicNumber               = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints            = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints           = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC              = "21,22";// Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing             = true;  // Enable trailing SL
input double          InpBreakevenRR               = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastSignalBarTime = 0;

// Symbol parameters cache
string  gSymbol;
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC) map
bool    gSkipHour[24];

//==================================================================
// Utility & Helpers
//==================================================================
void LogLastError(const string context)
{
  int err = GetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = hours_csv;
  StringTrimLeft(trimmed); StringTrimRight(trimmed);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = parts[i];
    StringTrimLeft(p); StringTrimRight(p);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }

  return true;
}

bool IndicatorsCreate()
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);

  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    LogLastError("Indicator handle creation failed");
    return false;
  }
  return true;
}

bool CopyLatest(const int handle, const int count, double &buf[])
{
  ArraySetAsSeries(buf,true);
  int copied = CopyBuffer(handle, 0, 0, count, buf);
  if(copied < count)
  {
    LogLastError("CopyBuffer failed");
    return false;
  }
  return true;
}

bool MarketIsOpenNow()
{
  datetime now = TimeCurrent();
  MqlDateTime t; TimeToStruct(now, t);
  int hourUTC = t.hour; // TimeCurrent is server time; assume server ~ UTC or user provided UTC list. For stricter, convert as needed.
  if(hourUTC>=0 && hourUTC<24 && gSkipHour[hourUTC]) return false;
  // Basic session check using trade session info
  bool session_open=false;
  if(SymbolInfoSessionTrade(gSymbol, 0, now, session_open))
  {
    if(!session_open) return false;
  }
  return true;
}

int CountOurPositions()
{
  int count=0;
  for(int i=PositionsTotal()-1;i>=0;i--)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(!PositionSelectByTicket(ticket)) continue;
    string sym = PositionGetString(POSITION_SYMBOL);
    ulong  mgc = (ulong)PositionGetInteger(POSITION_MAGIC);
    if(sym==gSymbol && mgc==InpMagicNumber) count++;
  }
  return count;
}

bool GetSpreadOK()
{
  double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);
  double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
  if(ask==0 || bid==0) return false;
  double spread_points = (ask - bid)/gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

// Calculate stop-loss and take-profit prices based on ATR and RR
bool CalcSLTP(const bool isBuy, double &sl, double &tp, double &atr_points)
{
  double atr_buf[3];
  if(!CopyLatest(hATR, 3, atr_buf)) return false;
  double atr = atr_buf[0];
  if(InpATR_MinFilter>0.0 && atr < InpATR_MinFilter) return false;

  double price = isBuy ? SymbolInfoDouble(gSymbol, SYMBOL_BID) : SymbolInfoDouble(gSymbol, SYMBOL_ASK);
  if(price<=0) return false;

  atr_points = InpATR_SL_Mult * (atr / gPoint);
  double sl_points = atr_points;
  double tp_points = InpRR * sl_points;

  if(isBuy)
  {
    sl = price - sl_points * gPoint;
    tp = price + tp_points * gPoint;
  }
  else
  {
    sl = price + sl_points * gPoint;
    tp = price - tp_points * gPoint;
  }

  // Respect stops level and freeze level
  double stop_dist_points = MathMax(gStopsLevelPoints, gFreezeLevelPoints+1);
  if(isBuy)
  {
    if((price - sl)/gPoint < stop_dist_points) sl = price - stop_dist_points * gPoint;
    if((tp - price)/gPoint < stop_dist_points) tp = price + stop_dist_points * gPoint;
  }
  else
  {
    if((sl - price)/gPoint < stop_dist_points) sl = price + stop_dist_points * gPoint;
    if((price - tp)/gPoint < stop_dist_points) tp = price - stop_dist_points * gPoint;
  }

  return true;
}

// Equity risk sizing with OrderCalcMargin checks and per-trade margin cap
bool ComputeVolumeByRisk(const bool isBuy, const double sl_price, double &volume_out, double &proj_margin_out)
{
  volume_out = 0.0; proj_margin_out = 0.0;

  double equity      = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(equity<=0 || free_margin<=0) return false;

  double entry = isBuy ? SymbolInfoDouble(gSymbol, SYMBOL_ASK) : SymbolInfoDouble(gSymbol, SYMBOL_BID);
  if(entry<=0) return false;

  // Risk amount in account currency
  double risk_amt = equity * (InpRiskPerTradePct/100.0);
  if(risk_amt <= 0) return false;

  // Pip/point value per 1 lot approximation
  if(gTickValue<=0 || gTickSize<=0) return false;
  double point_value_per_lot = (gPoint / gTickSize) * gTickValue; // value of one point per 1 lot

  double stop_distance_points = MathAbs(entry - sl_price)/gPoint;
  if(stop_distance_points <= 0) return false;

  double vol_by_risk = risk_amt / (stop_distance_points * point_value_per_lot);

  // Clamp to broker volume constraints
  double vol = MathMax(gMinVolume, MathMin(vol_by_risk, gMaxVolume));
  // Align to step
  vol = MathFloor(vol / gVolStep) * gVolStep;
  if(vol < gMinVolume) return false;

  // Margin check: estimate margin per lot then apply per-trade cap
  double margin_for_vol = 0.0;
  if(!OrderCalcMargin(isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL, gSymbol, vol, entry, margin_for_vol))
  {
    LogLastError("OrderCalcMargin failed");
    return false;
  }

  // Per-trade margin cap based on free margin percentage
  double max_allowed_margin = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(max_allowed_margin <= 0) return false;

  // If margin exceeds cap, scale volume down
  if(margin_for_vol > max_allowed_margin && margin_for_vol > 0)
  {
    double scale = max_allowed_margin / margin_for_vol;
    vol = vol * scale;
    vol = MathFloor(vol / gVolStep) * gVolStep;
    if(vol < gMinVolume) return false;

    if(!OrderCalcMargin(isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL, gSymbol, vol, entry, margin_for_vol))
    {
      LogLastError("OrderCalcMargin (rescaled) failed");
      return false;
    }
  }

  // Projected margin level check
  double used_margin = AccountInfoDouble(ACCOUNT_MARGIN);
  double equity_after = equity; // equity unchanged at entry
  double margin_after = used_margin + margin_for_vol;
  double margin_level_after = (margin_after>0.0) ? (equity_after / margin_after * 100.0) : 9999.0;
  if(InpMinMarginLevelPct > 0.0 && margin_level_after < InpMinMarginLevelPct)
  {
    PrintFormat("Projected margin level %.1f%% < min %.1f%%; abort entry", margin_level_after, InpMinMarginLevelPct);
    return false;
  }

  // Free margin after
  double free_margin_after = free_margin - margin_for_vol;
  if(free_margin_after <= 0)
  {
    Print("Insufficient free margin after planned entry");
    return false;
  }

  volume_out = vol;
  proj_margin_out = margin_for_vol;
  return true;
}

bool PlaceOrder(const bool isBuy, const double volume, const double sl, const double tp)
{
  MqlTradeRequest  req;  ZeroMemory(req);
  MqlTradeResult   res;  ZeroMemory(res);

  double price = isBuy ? SymbolInfoDouble(gSymbol, SYMBOL_ASK) : SymbolInfoDouble(gSymbol, SYMBOL_BID);
  if(price<=0) return false;

  req.action   = TRADE_ACTION_DEAL;
  req.symbol   = gSymbol;
  req.magic    = InpMagicNumber;
  req.type     = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  req.volume   = volume;
  req.price    = price;
  req.sl       = sl;
  req.tp       = tp;
  req.deviation= InpSlippagePoints;
  req.type_filling = ORDER_FILLING_FOK;
  req.type_time    = ORDER_TIME_GTC;

  if(!OrderSend(req, res))
  {
    LogLastError("OrderSend failed");
    return false;
  }
  if(res.retcode != TRADE_RETCODE_DONE)
  {
    PrintFormat("OrderSend retcode=%d (%s)", res.retcode, res.comment);
    return false;
  }

  return true;
}

void ManagePositionTrailing()
{
  if(!InpAllowTrailing) return;

  for(int i=PositionsTotal()-1;i>=0;i--)
  {
    if(!PositionSelectByTicket(PositionGetTicket(i))) continue;
    if(PositionGetString(POSITION_SYMBOL)!=gSymbol) continue;
    if((ulong)PositionGetInteger(POSITION_MAGIC)!=InpMagicNumber) continue;

    long    type  = PositionGetInteger(POSITION_TYPE);
    double  price_open = PositionGetDouble(POSITION_PRICE_OPEN);
    double  sl    = PositionGetDouble(POSITION_SL);
    double  tp    = PositionGetDouble(POSITION_TP);
    double  volume= PositionGetDouble(POSITION_VOLUME);

    double ema_fast_buf[3], ema_slow_buf[3], rsi_buf[3], atr_buf[3]; // for potential BE logic use ATR
    CopyLatest(hATR, 3, atr_buf);
    double atr = atr_buf[0];
    double trail_dist = InpATR_TrailMult * atr; // in price units

    double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
    double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);

    // Move to breakeven at given RR
    if(InpBreakevenRR>0.0)
    {
      double initial_sl_dist = MathAbs(price_open - sl);
      if(initial_sl_dist>0)
      {
        double be_trigger = price_open + ((type==POSITION_TYPE_BUY)? 1:-1) * (InpBreakevenRR * initial_sl_dist);
        if(type==POSITION_TYPE_BUY && bid >= be_trigger && sl < price_open)
        {
          MqlTradeRequest  r; ZeroMemory(r);
          MqlTradeResult   s; ZeroMemory(s);
          r.action = TRADE_ACTION_SLTP;
          r.symbol = gSymbol;
          r.magic  = InpMagicNumber;
          r.sl     = price_open;
          r.tp     = tp;
          if(!OrderSend(r,s)) LogLastError("Move SL to BE failed");
        }
        else if(type==POSITION_TYPE_SELL && ask <= be_trigger && (sl==0.0 || sl > price_open))
        {
          MqlTradeRequest  r; ZeroMemory(r);
          MqlTradeResult   s; ZeroMemory(s);
          r.action = TRADE_ACTION_SLTP;
          r.symbol = gSymbol;
          r.magic  = InpMagicNumber;
          r.sl     = price_open;
          r.tp     = tp;
          if(!OrderSend(r,s)) LogLastError("Move SL to BE failed");
        }
      }
    }

    // ATR trailing
    if(type==POSITION_TYPE_BUY)
    {
      double new_sl = bid - trail_dist;
      // Respect stop/freeze distances
      double min_dist = MathMax(gStopsLevelPoints, gFreezeLevelPoints+1) * gPoint;
      if((bid - new_sl) < min_dist) new_sl = bid - min_dist;
      if(new_sl > sl)
      {
        MqlTradeRequest  r; ZeroMemory(r);
        MqlTradeResult   s; ZeroMemory(s);
        r.action = TRADE_ACTION_SLTP;
        r.symbol = gSymbol;
        r.magic  = InpMagicNumber;
        r.sl     = NormalizeDouble(new_sl, gDigits);
        r.tp     = tp;
        if(!OrderSend(r,s)) LogLastError("Trailing SL (buy) failed");
      }
    }
    else if(type==POSITION_TYPE_SELL)
    {
      double new_sl = ask + trail_dist;
      double min_dist = MathMax(gStopsLevelPoints, gFreezeLevelPoints+1) * gPoint;
      if((new_sl - ask) < min_dist) new_sl = ask + min_dist;
      if(new_sl < sl || sl==0.0)
      {
        MqlTradeRequest  r; ZeroMemory(r);
        MqlTradeResult   s; ZeroMemory(s);
        r.action = TRADE_ACTION_SLTP;
        r.symbol = gSymbol;
        r.magic  = InpMagicNumber;
        r.sl     = NormalizeDouble(new_sl, gDigits);
        r.tp     = tp;
        if(!OrderSend(r,s)) LogLastError("Trailing SL (sell) failed");
      }
    }
  }
}

bool GenerateSignal(const int shift, bool &buy, bool &sell)
{
  buy=false; sell=false;

  double f[3], s[3], r[3];
  if(!CopyLatest(hFastEMA, 3, f)) return false;
  if(!CopyLatest(hSlowEMA, 3, s)) return false;
  if(!CopyLatest(hRSI,     3, r)) return false;

  // Use previous completed bar(s) to avoid repaint
  double f_prev = f[1+shift];
  double s_prev = s[1+shift];
  double r_prev = r[1+shift];

  // Cross logic with RSI filter
  if(f_prev > s_prev && r_prev >= InpRSI_Buy)
    buy = true;
  else if(f_prev < s_prev && r_prev <= InpRSI_Sell)
    sell = true;

  return true;
}

//==================================================================
// Standard EA functions
//==================================================================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Symbol info init failed");
    return(INIT_FAILED);
  }

  ParseSkipHours(InpSkipHoursUTC);

  if(!IndicatorsCreate())
  {
    Print("Indicator creation failed");
    return(INIT_FAILED);
  }

  trade.SetExpertMagicNumber((int)InpMagicNumber);
  return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(!RefreshSymbolInfo(_Symbol)) return;

  // Only act on new bar for the signal timeframe to reduce noise
  static datetime lastBarTime = 0;
  datetime times[2];
  ArraySetAsSeries(times,true);
  if(CopyTime(gSymbol, InpTimeframe, 0, 2, times) < 2) return;
  if(times[0] == 0) return;

  bool isNewBar = (times[0] != lastBarTime);

  // Always manage trailing each tick
  ManagePositionTrailing();

  if(!isNewBar) return;
  lastBarTime = times[0];

  // Filters
  if(!MarketIsOpenNow()) { Print("Session filter blocks trading now"); return; }
  if(!GetSpreadOK())     { Print("Spread filter blocks trading now");  return; }

  // One-position-per-symbol rule
  if(CountOurPositions() > 0) { Print("Position already open - skip new entries"); return; }

  // Generate signals on closed bar
  bool buy=false, sell=false;
  if(!GenerateSignal(0, buy, sell)) return;

  // Prepare SL/TP using ATR
  double sl=0.0, tp=0.0, atr_pts=0.0;

  if(buy)
  {
    if(!CalcSLTP(true, sl, tp, atr_pts)) { Print("Failed to calc SLTP (buy)"); return; }

    double volume=0.0, proj_margin=0.0;
    if(!ComputeVolumeByRisk(true, sl, volume, proj_margin)) { Print("Risk sizing failed (buy)"); return; }

    if(!PlaceOrder(true, volume, NormalizeDouble(sl, gDigits), NormalizeDouble(tp, gDigits)))
    {
      Print("PlaceOrder BUY failed");
    }
  }
  else if(sell)
  {
    if(!CalcSLTP(false, sl, tp, atr_pts)) { Print("Failed to calc SLTP (sell)"); return; }

    double volume=0.0, proj_margin=0.0;
    if(!ComputeVolumeByRisk(false, sl, volume, proj_margin)) { Print("Risk sizing failed (sell)"); return; }

    if(!PlaceOrder(false, volume, NormalizeDouble(sl, gDigits), NormalizeDouble(tp, gDigits)))
    {
      Print("PlaceOrder SELL failed");
    }
  }
}

//==================================================================
// Notes:
// - This EA enforces one-position-per-symbol via CountOurPositions().
// - Risk sizing uses equity-based risk with OrderCalcMargin checks and a per-trade margin cap.
// - Additional runtime protections: spread filter, session filter, stops/freeze compliance.
// - Always forward-test and optimize on a demo before going live.
//==================================================================

//+------------------------------------------------------------------+
//|                                               EMA_RSI_Manager.mq5 |
//|  EMA Cross + RSI with robust risk & margin controls               |
//|  One-position-per-symbol, spread/session filters, trailing stop   |
//+------------------------------------------------------------------+
#property copyright   ""
#property version     "1.00"
#property strict

//--- Inputs
input string   InpSymbols           = "EURUSD,GBPUSD,XAUUSD"; // Comma-separated symbols to trade
input ENUM_TIMEFRAMES InpTF         = PERIOD_M15;             // Working timeframe
input int      InpFastEMA           = 21;                     // Fast EMA period
input int      InpSlowEMA           = 50;                     // Slow EMA period
input int      InpRSIPeriod         = 14;                     // RSI period
input int      InpRSIOverbought     = 70;                     // RSI overbought
input int      InpRSIOversold       = 30;                     // RSI oversold

input double   InpRiskPerTradePct   = 0.5;                    // Risk per trade (% of free margin)
input double   InpPerTradeMarginCap = 2.0;                    // Max margin per trade (% of free margin)
input double   InpMinMarginLevel    = 200.0;                  // Minimum margin level % to allow new trades

input double   InpSL_Pips           = 150;                    // Fixed SL in pips (symbol pip definition)
input double   InpTP_Pips           = 300;                    // Fixed TP in pips
input bool     InpUseTrailing       = true;                   // Enable trailing stop
input double   InpTrailStartPips    = 200;                    // Start trailing when profit >= this many pips
input double   InpTrailStepPips     = 50;                     // Trail step in pips

input double   InpMaxSpreadPips     = 20;                     // Skip trading if spread > this (pips)
input bool     InpUseSessionFilter  = true;                   // Restrict trading to sessions
input int      InpSessionStartHour  = 7;                      // Trading start hour (server time)
input int      InpSessionEndHour    = 20;                     // Trading end hour (server time)

input bool     InpAllowLongs        = true;                   // Allow buy trades
input bool     InpAllowShorts       = true;                   // Allow sell trades
input bool     InpDebug             = true;                   // Print debug logs

//--- Constants/util
#define INVALID_POSITION_TICKET -1

//--- State
string  g_symbols[];
int     g_magic = 870015;

//--- Helper: pip size for symbol
double PipSize(const string sym)
{
  double pip = SymbolInfoDouble(sym, SYMBOL_POINT);
  int    digits = (int)SymbolInfoInteger(sym, SYMBOL_DIGITS);
  // For 5-digit FX symbols, 1 pip = 10 points; for 3-digit JPY crosses, 1 pip = 0.01
  if(digits == 3 || digits == 5)
    return pip * 10.0;
  return pip;
}

//--- Helper: spread in pips
double SpreadPips(const string sym)
{
  double spread_pts = SymbolInfoInteger(sym, SYMBOL_SPREAD) * SymbolInfoDouble(sym, SYMBOL_POINT);
  return spread_pts / PipSize(sym);
}

//--- Helper: session filter
bool InSession()
{
  if(!InpUseSessionFilter) return true;
  datetime now = TimeCurrent();
  MqlDateTime t; TimeToStruct(now, t);
  if(InpSessionStartHour <= InpSessionEndHour)
    return (t.hour >= InpSessionStartHour && t.hour < InpSessionEndHour);
  // Overnight wrap
  return (t.hour >= InpSessionStartHour || t.hour < InpSessionEndHour);
}

//--- Get EMA value
bool GetEMA(const string sym, ENUM_TIMEFRAMES tf, int period, int shift, double &val)
{
  double buf[];
  if(iMA(sym, tf, period, 0, MODE_EMA, PRICE_CLOSE) == INVALID_HANDLE)
    return false;
  if(CopyBuffer(iMA(sym, tf, period, 0, MODE_EMA, PRICE_CLOSE), 0, shift, 2, buf) != 2)
    return false;
  val = buf[0];
  return true;
}

//--- Get RSI value
bool GetRSI(const string sym, ENUM_TIMEFRAMES tf, int period, int shift, double &val)
{
  double buf[];
  int h = iRSI(sym, tf, period, PRICE_CLOSE);
  if(h == INVALID_HANDLE) return false;
  if(CopyBuffer(h, 0, shift, 2, buf) != 2) return false;
  val = buf[0];
  return true;
}

//--- One position per symbol: find existing position
bool HasOpenPosition(const string sym, ulong &ticket, long &type)
{
  ticket = INVALID_POSITION_TICKET;
  type = -1;
  if(!PositionSelect(sym)) return false;
  ticket = (ulong)PositionGetInteger(POSITION_TICKET);
  type   = PositionGetInteger(POSITION_TYPE);
  return true;
}

//--- Calculate lot size using OrderCalcMargin and risk/margin constraints
bool CalculateLots(const string sym, bool isBuy, double sl_price, double risk_pct, double margin_cap_pct, double &lots_out, string &err)
{
  lots_out = 0.0;

  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double balance     = AccountInfoDouble(ACCOUNT_BALANCE);
  double equity      = AccountInfoDouble(ACCOUNT_EQUITY);

  if(free_margin <= 0.0) { err = "No free margin"; return false; }

  // Determine tick/pip value per lot
  double tick_size  = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_SIZE);
  double tick_value = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
  double point      = SymbolInfoDouble(sym, SYMBOL_POINT);
  double pip        = PipSize(sym);
  if(tick_size <= 0 || tick_value <= 0 || point <= 0) { err = "Invalid symbol parameters"; return false; }

  // Risk in money
  double max_risk_money = MathMax(0.0, free_margin * (risk_pct/100.0));
  if(max_risk_money <= 0.0) { err = "Risk budget is zero"; return false; }

  // Estimate SL distance in price
  double price = isBuy ? SymbolInfoDouble(sym, SYMBOL_ASK) : SymbolInfoDouble(sym, SYMBOL_BID);
  if(price <= 0 || sl_price <= 0) { err = "Invalid price or SL"; return false; }
  double sl_distance = MathAbs(price - sl_price);
  if(sl_distance < point) { err = "SL too close"; return false; }

  // Convert SL distance to ticks
  double ticks_per_price = 1.0 / tick_size;
  double ticks_at_sl = sl_distance * ticks_per_price;
  if(ticks_at_sl <= 0) { err = "Computed ticks_at_sl <= 0"; return false; }

  // Money lost per 1 lot if SL hits
  double loss_per_lot = ticks_at_sl * tick_value;
  if(loss_per_lot <= 0) { err = "loss_per_lot <= 0"; return false; }

  // Risk-based lots (capped by max risk money)
  double lots_risk = max_risk_money / loss_per_lot;

  // Margin-based cap using OrderCalcMargin with free-margin and per-trade margin cap
  double max_margin_money = free_margin * (margin_cap_pct/100.0);

  double lot_step  = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
  double min_lot   = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
  double max_lot   = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
  if(lot_step <= 0 || min_lot <= 0 || max_lot <= 0) { err = "Invalid lot constraints"; return false; }

  // Start with risk-based lots, then reduce until both margin and min requirements are respected
  double lots = MathMax(min_lot, MathMin(lots_risk, max_lot));

  auto NormalizeLot = [&](double v)->double{
    double steps = MathFloor((v - min_lot + 1e-12)/lot_step);
    double out = min_lot + MathMax(0.0, steps) * lot_step;
    return MathMin(MathMax(out, min_lot), max_lot);
  };

  lots = NormalizeDouble(NormalizeLot(lots), (int)MathRound(-MathLog10(lot_step)));

  // Check per-trade margin using OrderCalcMargin and free margin
  double margin_req = 0.0;
  while(lots >= min_lot - 1e-12)
  {
    if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, lots, price, margin_req))
    { err = "OrderCalcMargin failed (" + IntegerToString(GetLastError()) + ")"; return false; }

    if(margin_req <= 0) { err = "Invalid margin requirement"; return false; }

    if(margin_req <= max_margin_money && margin_req < free_margin)
      break; // acceptable

    lots -= lot_step;
    lots = NormalizeLot(lots);
    lots = NormalizeDouble(lots, (int)MathRound(-MathLog10(lot_step)));
  }

  if(lots < min_lot - 1e-12)
  { err = "Lots reduced below minimum due to margin cap"; return false; }

  lots_out = lots;
  return true;
}

//--- Determine trade signal
int Signal(const string sym)
{
  // 1 = buy, -1 = sell, 0 = none
  double ema_fast_c, ema_slow_c, ema_fast_p, ema_slow_p, rsi_c;
  if(!GetEMA(sym, InpTF, InpFastEMA, 0, ema_fast_c))   return 0;
  if(!GetEMA(sym, InpTF, InpSlowEMA, 0, ema_slow_c))   return 0;
  if(!GetEMA(sym, InpTF, InpFastEMA, 1, ema_fast_p))   return 0;
  if(!GetEMA(sym, InpTF, InpSlowEMA, 1, ema_slow_p))   return 0;
  if(!GetRSI(sym, InpTF, InpRSIPeriod, 0, rsi_c))      return 0;

  bool bull_cross = (ema_fast_p <= ema_slow_p) && (ema_fast_c > ema_slow_c) && (rsi_c > InpRSIOversold);
  bool bear_cross = (ema_fast_p >= ema_slow_p) && (ema_fast_c < ema_slow_c) && (rsi_c < InpRSIOverbought);

  if(bull_cross && InpAllowLongs) return 1;
  if(bear_cross && InpAllowShorts) return -1;
  return 0;
}

//--- Build SL/TP prices given pips
bool BuildSLTP(const string sym, bool isBuy, double sl_pips, double tp_pips, double &sl, double &tp)
{
  double pip = PipSize(sym);
  double ask = SymbolInfoDouble(sym, SYMBOL_ASK);
  double bid = SymbolInfoDouble(sym, SYMBOL_BID);
  if(ask<=0 || bid<=0) return false;

  if(isBuy)
  {
    sl = bid - sl_pips * pip;
    tp = bid + tp_pips * pip;
  }
  else
  {
    sl = ask + sl_pips * pip;
    tp = ask - tp_pips * pip;
  }
  return true;
}

//--- Send order with full checks and error handling
bool OpenTrade(const string sym, int dir, string &err)
{
  bool isBuy = (dir == 1);
  double sl=0, tp=0;
  if(!BuildSLTP(sym, isBuy, InpSL_Pips, InpTP_Pips, sl, tp)) { err = "Failed to build SL/TP"; return false; }

  // Margin level check before trading
  double margin_level = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);
  if(margin_level > 0 && margin_level < InpMinMarginLevel) { err = "Margin level too low"; return false; }

  // Position sizing via OrderCalcMargin with per-trade cap
  double lots = 0.0; string sizing_err;
  if(!CalculateLots(sym, isBuy, sl, InpRiskPerTradePct, InpPerTradeMarginCap, lots, sizing_err))
  { err = "Sizing failed: " + sizing_err; return false; }

  MqlTradeRequest req; MqlTradeResult res; ZeroMemory(req); ZeroMemory(res);
  req.action   = TRADE_ACTION_DEAL;
  req.symbol   = sym;
  req.magic    = g_magic;
  req.type     = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  req.price    = isBuy ? SymbolInfoDouble(sym, SYMBOL_ASK) : SymbolInfoDouble(sym, SYMBOL_BID);
  req.sl       = sl;
  req.tp       = tp;
  req.volume   = lots;
  req.deviation= 20; // adjust to broker
  req.type_filling = ORDER_FILLING_FOK;
  req.comment  = "EMA_RSI_Manager";

  if(!OrderSend(req, res))
  { err = "OrderSend failed: " + IntegerToString(GetLastError()); return false; }

  if(res.retcode != TRADE_RETCODE_DONE)
  { err = "Trade rejected: retcode=" + IntegerToString((int)res.retcode); return false; }

  return true;
}

//--- Trailing stop logic per symbol (one position per symbol)
void TrailPosition(const string sym)
{
  if(!PositionSelect(sym)) return;
  long   type   = PositionGetInteger(POSITION_TYPE);
  double price_open = PositionGetDouble(POSITION_PRICE_OPEN);
  double sl     = PositionGetDouble(POSITION_SL);
  double volume = PositionGetDouble(POSITION_VOLUME);

  double bid = SymbolInfoDouble(sym, SYMBOL_BID);
  double ask = SymbolInfoDouble(sym, SYMBOL_ASK);
  double pip = PipSize(sym);

  if(volume <= 0) return;

  if(type == POSITION_TYPE_BUY)
  {
    double profit_pips = (bid - price_open)/pip;
    if(profit_pips >= InpTrailStartPips)
    {
      double new_sl = bid - InpTrailStepPips * pip;
      if(sl < new_sl)
      {
        MqlTradeRequest req; MqlTradeResult res; ZeroMemory(req); ZeroMemory(res);
        req.action = TRADE_ACTION_SLTP;
        req.symbol = sym;
        req.magic  = g_magic;
        req.sl     = new_sl;
        req.tp     = PositionGetDouble(POSITION_TP);
        if(!OrderSend(req, res) || res.retcode != TRADE_RETCODE_DONE)
        {
          if(InpDebug) Print("Trailing SL update failed for ", sym, " retcode=", res.retcode, " err=", GetLastError());
        }
      }
    }
  }
  else if(type == POSITION_TYPE_SELL)
  {
    double profit_pips = (price_open - ask)/pip;
    if(profit_pips >= InpTrailStartPips)
    {
      double new_sl = ask + InpTrailStepPips * pip;
      if(sl == 0 || sl > new_sl)
      {
        MqlTradeRequest req; MqlTradeResult res; ZeroMemory(req); ZeroMemory(res);
        req.action = TRADE_ACTION_SLTP;
        req.symbol = sym;
        req.magic  = g_magic;
        req.sl     = new_sl;
        req.tp     = PositionGetDouble(POSITION_TP);
        if(!OrderSend(req, res) || res.retcode != TRADE_RETCODE_DONE)
        {
          if(InpDebug) Print("Trailing SL update failed for ", sym, " retcode=", res.retcode, " err=", GetLastError());
        }
      }
    }
  }
}

//--- OnInit: parse symbols and basic checks
int OnInit()
{
  StringSplit(InpSymbols, ',', g_symbols);
  if(ArraySize(g_symbols) <= 0)
  {
    Print("No symbols configured");
    return INIT_PARAMETERS_INCORRECT;
  }

  for(int i=0;i<ArraySize(g_symbols);++i)
  {
    string s = StringTrim(g_symbols[i]);
    g_symbols[i] = s;
    // Ensure symbol is available
    if(!SymbolSelect(s, true))
    {
      Print("Failed to select symbol ", s);
      return INIT_FAILED;
    }
  }

  return INIT_SUCCEEDED;
}

//--- Pre-trade guardrails
bool CanTradeSymbol(const string sym)
{
  // Spread filter
  if(SpreadPips(sym) > InpMaxSpreadPips)
  {
    if(InpDebug) Print("Skip ", sym, ": spread too high (", DoubleToString(SpreadPips(sym),1), ")");
    return false;
  }
  // Session filter
  if(!InSession())
  {
    if(InpDebug) Print("Skip ", sym, ": out of session");
    return false;
  }
  // Trading allowed check
  if(!TerminalInfoInteger(TERMINAL_CONNECTED) || !MQLInfoInteger(MQL_TRADE_ALLOWED))
  {
    if(InpDebug) Print("Trading not allowed or terminal disconnected");
    return false;
  }
  // Symbol trade mode
  long trade_mode = (long)SymbolInfoInteger(sym, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED)
  {
    if(InpDebug) Print("Symbol disabled: ", sym);
    return false;
  }
  return true;
}

//--- OnTick: per-symbol logic, one position per symbol, entries, trailing
void OnTick()
{
  static datetime last_run = 0;
  datetime now = TimeCurrent();
  if(now == last_run) return; // avoid multiple executions per second burst
  last_run = now;

  for(int i=0;i<ArraySize(g_symbols);++i)
  {
    string sym = g_symbols[i];
    if(sym == "") continue;

    if(!CanTradeSymbol(sym)) continue;

    // One position per symbol
    ulong pos_ticket; long pos_type;
    bool has_pos = HasOpenPosition(sym, pos_ticket, pos_type);

    // Manage trailing if position exists
    if(has_pos && InpUseTrailing)
      TrailPosition(sym);

    // If already have a position, skip new entries
    if(has_pos) continue;

    // Entry logic
    int sig = Signal(sym);
    if(sig == 0) continue;

    string err;
    if(!OpenTrade(sym, sig, err))
    {
      if(InpDebug) Print("OpenTrade failed for ", sym, ": ", err);
    }
  }
}

//--- Deinit
void OnDeinit(const int reason)
{
  if(InpDebug) Print("Deinit reason=", reason);
}
